      { name: "Zauberwirken", beschreibung: "Der Abishai ist ein Zauberwirker der 13. Stufe. Sein Attribut zum Zauberwirken ist Intelligenz (Zauberrettungswurf-SG 20, +12 zum Treffen mit Zauberangriffen). Er hat die folgenden Magierzaubersprüche vorbereitet: Zaubertricks (beliebig oft): Botschaft, Einfache Illusion, Freundschaft, Magierhand, Schockgriff. 1. Grad (4 Plätze): Chromatische Kugel, Donnerwoge, Magisches Geschoss, Person bezaubern, Rascher Rückzug, Selbstverkleidung. 2. Grad (3 Plätze): Dunkelheit, Nebelschritt, Spiegelbilder. 3. Grad (3 Plätze): Blitz, Furcht, Magie bannen. 4. Grad (3 Plätze): Dimensionstür, Eissturm, Mächtige Unsichtbarkeit. 5. Grad (2 Plätze): Energiewand, Kältekegel. 6. Grad (1 Platz): Kugelblitz. 7. Grad (1 Platz): Teleportieren." }
