      "Ihre diplomatischen Fertigkeiten und ihre Kontrollmagie stellen sicher, dass sie selbst die gewieftesten Gegenspieler manipulieren können — sei es durch Bezauberung, Gedankenleserei oder Massenbeherrschung."
