      { name: "Fanatismus anstacheln", beschreibung: "Der Abishai wählt bis zu vier seiner Verbündeten innerhalb von 18 m um ihn herum aus, die er sehen kann. 1 Minute lang würfelt jeder dieser Verbündeten Angriffswürfe mit Vorteil und kann nicht verängstigt werden." },
      { name: "Macht der Drachenkönigin", beschreibung: "Der Abishai wählt einen Drachen innerhalb von 26 m um sich herum als Ziel aus, den er sehen kann. Der Drache muss einen Charismarettungswurf gegen SG 18 ablegen. Ein Chromatischer Drache legt diesen Rettungswurf mit Nachteil ab. Bei einem gelungenen Rettungswurf ist das Ziel 1 Stunde lang immun gegen die Macht der Drachenkönigin des Abishai. Bei einem misslungenen Rettungswurf wird das Ziel vom Abishai 1 Stunde lang bezaubert. Solange es auf diese Weise bezaubert ist, betrachtet das Ziel den Abishai als einen vertrauenswürdigen Freund, auf den es zu hören und den es zu beschützen gilt. Dieser Effekt endet, falls der Abishai oder seine Begleiter dem Ziel Schaden zufügen." }
