    umgebung: [],
    bild: "assets/images/monster/foliant/allip.png",
    beschreibung: [
      "Wenn ein Geheimnis aufgedeckt wird, das von einer mächtigen Kreatur mit einem Fluch geschützt wurde, entsteht oft ein Allip. Derart geschützte Geheimnisse reichen vom wahren Namen eines dämonischen Fürsten bis hin zur versteckten Wahrheit über die Ordnung des Kosmos. Lüftet eine Kreatur ein solches Geheimnis, zerstört der Fluch ihren Körper, hinterlässt dabei jedoch eine geisterhafte Kreatur aus Fragmenten des Bewusstseins des Opfers und überwältigenden psychischen Qualen — einen Allip.",
      "Quälende Geheimnisse. Jeder Allip wird von furchtbaren Erkenntnissen geplagt, die die Überreste seines Verstands quälen. In der Gegenwart anderer Kreaturen will er seine Geheimnisse mit ihnen teilen, um die eigenen Qualen zu lindern. Zwar kann der Allip nur einen Bruchteil des Wissens, das ihn verdammt hat, vermitteln, doch auch dieser Bruchteil reicht aus, um den Empfänger vorübergehend in den Wahnsinn zu treiben. Jene, die den Angriff eines Allips überleben, fühlen manchmal den Drang, mehr darüber zu erfahren, was dieses Monster erschaffen hat. Ihr Verstand wird von seltsamen Echos heimgesucht, die von merkwürdigen Visionen begleitet werden. Das Gefühl, einer Wahrheit gigantischen Ausmaßes nahe zu sein, plagt sie über Tage, Monate oder manchmal Jahre, nachdem sie die Kreatur getroffen haben.",
      "Untote Natur. Allips müssen nicht atmen, essen, trinken oder schlafen.",
      "Heimtückisches Wissen. Der Allip könnte versuchen, sein Wissen mit einer anderen Kreatur zu teilen, um seinen Fluch zu brechen und ein richtiges Nachleben anzufangen. Er kann sein Wissen weitergeben, indem er eine Kreatur dazu bringt, dieses niederzuschreiben. Dieser Vorgang kann Tage oder sogar Wochen dauern. Um dieses Ziel zu erreichen, kann ein Allip das Arbeitszimmer eines Gelehrten heimsuchen. Bleibt der Allip verborgen, erliegt das Opfer nach und nach einer manischen Energie. Der Gelehrte wird von plötzlichen Erkenntnissen getrieben und arbeitet Tag und Nacht. Dabei entstehen ganze Berge an Text, das Opfer kann sich aber kaum an den Inhalt erinnern. Ist der Allip erfolgreich, kann er diese Welt verlassen. Sein furchtbares Geheimnis bleibt in den Texten des Gelehrten versteckt und wartet nur darauf, vom nächsten Opfer entdeckt zu werden."
    ],
    besonderheiten: [
      { name: "Körperlose Bewegung", beschreibung: "Der Allip kann sich durch andere Kreaturen hindurch bewegen. In diesem Fall gelten sie als schwieriges Gelände. Endet der Zug des Allips innerhalb eines Objekts, nimmt der Allip 5 (1W10) Schaden." }
    ],
    aktionen: [
      { name: "Berührung des Wahnsinns", beschreibung: "Nahkampf Zauberangriff: +6 zum Treffen, Reichweite 1,50 m, eine Kreatur. Treffer: 17 (4W6+3) psychischer Schaden." },
      { name: "Wahnsinnsgeflüster", beschreibung: "Der Allip kann bis zu drei Kreaturen in einem Umkreis von 18 m auswählen, die er sehen kann. Jede dieser Kreaturen muss einen Weisheitsrettungswurf gegen SG 14 ablegen oder 7 (1W8+3) psychischen Schaden nehmen und als Reaktion einen Nahkampfangriff gegen eine Kreatur im Sichtbereich des Allips ausführen, die er auswählt. Konstrukte und Untote sind gegen diesen Effekt immun." },
      { name: "Heulendes Plappern (Aufladung 6)", beschreibung: "Jede Kreatur, die der Allip im Umkreis von 9 m hören kann, muss einen Weisheitsrettungswurf gegen SG 14 ablegen. Misslingt der Wurf, nimmt das Ziel 12 (2W8+3) psychischen Schaden und ist bis zum Ende seines nächsten Zugs betäubt. Bei einem Erfolg wird der Schaden halbiert und die Kreatur ist nicht betäubt. Konstrukte und Untote sind gegen diesen Effekt immun." }
    ],
    bonusaktionen: [], reaktionen: [], legendaere_aktionen: null,
    source: "Foliant der Feinde"
