    bild: "assets/images/monster/foliant/aeltester_oblex.png",
    beschreibung: [
      "Ältere oblexe, Ausgewachsene und Älteste genannt, haben so viele Erinnerungen gefressen, dass sie aus ihrer Körpersubstanz Duplikate der verschlungenen Kreaturen formen können. Diese schicken sie aus, um ihnen Beute anzulocken, während sie mit langen, schmierigen Fasern am Schleim angeleint bleiben. Diese duplizierten Kreaturen sind nicht von den Opfern des oblex zu unterscheiden, mit Ausnahme eines schwachen schwefligen Geruchs. oblexe benutzen diese Duplikate, um Beute in Gefahr zu locken oder Siedlungen zu infiltrieren."
    ],
    besonderheiten: [
      { name: "Abneigung gegen Feuer", beschreibung: "Wenn der oblex Feuerschaden erleidet, hat er bis zum Ende seines nächsten Zuges einen Nachteil bei Angriffswürfen und Attributswürfen." },
      { name: "Amorph", beschreibung: "Der oblex kann sich durch einen Bereich bewegen, der nicht größer als 2,50 cm ist, ohne sich quetschen zu müssen." },
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Zauberwirkungsattribut des oblex ist Intelligenz (Zauberrettungswurf-SG 18). Er kann die folgenden Zauber angeboren wirken, ohne Komponenten zu benötigen. Beliebig oft: Gedanken wahrnehmen, Person bezaubern (als Zauberspruch des 5. Grades), Person festhalten (als Zauberspruch des 5. Grades). Jeweils 3/Tag: Dimensionstür, Furcht, Hypnotisches Muster, Person beherrschen, Scheingelände, Telekinese, Verwirrung." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Älteste oblex führt einen Scheinfuß-Angriff aus und benutzt Erinnerungen fressen." },
      { name: "Scheinfuß", beschreibung: "Nahkampf-Waffenangriff: +7 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 17 (4W6+3) Wuchtschaden plus 7 (2W6) psychischer Schaden." },
      { name: "Erinnerungen fressen", beschreibung: "Der oblex wählt eine Kreatur als Ziel aus, die er innerhalb von 1,50 m sehen kann. Dem Ziel muss ein Weisheitsrettungswurf gegen SG 18 gelingen, sonst erleidet es 18 (4W8) psychischen Schaden und einen Erinnerungsschwund, bis es eine kurze oder lange Rast beendet hat oder von einem Zauber Vollständige Genesung oder Heilung profitiert. Konstrukten, Pflanzen, Schlicken und Untoten gelingt der Rettungswurf automatisch. Solange es am Erinnerungsschwund leidet, muss das Ziel mit einem W4 würfeln und die Augenzahl von jedem Fertigkeitswurf oder Angriffswurf abziehen. Jedes weitere Mal erhöht sich die Würfelgröße um eins: W4→W6→W8 und so weiter bis W20. Bei W20 wird das Opfer 1 Stunde lang bewusstlos. Wenn ein oblex einem Ziel Erinnerungsschwund zufügt, erlernt er alle Sprachen des Opfers und erhält all seine Übungen außer denen in Rettungswürfen." }
    ],
    bonusaktionen: [
      { name: "Schweflige Verkörperung", beschreibung: "Der oblex stülpt einen Teil seiner selbst aus, der das Erscheinungsbild einer mittelgroßen oder kleineren Kreatur annimmt, deren Erinnerungen er gestohlen hat. Dieses Simulakrum erscheint, fühlt sich an und klingt exakt so wie die Kreatur, obwohl es leicht nach Schwefel riecht. Der oblex kann 2W6+1 verschiedene Kreaturen verkörpern, von denen jede durch einen Strang aus Schleim an seinen Körper angeleint ist, der sich bis zu 36 m erstrecken kann. Das Simulakrum ist für alle praktischen Zwecke der oblex; er besetzt seinen eigenen Bereich und den des Simulakrums gleichzeitig. Die schleimige Halteleine ist immun gegen Schaden, wird aber abgetrennt, falls sich zwischen Hauptkörper und Simulakrum keine Öffnung von mindestens 2,50 cm Breite befindet. Das Simulakrum verschwindet, falls die Halteleine abgetrennt wird." }
    ],
