    beschreibung: [
      "Die krankhaften Bulezaus verkörpern den animalischen Zorn und die Brutalität der Natur. Diese Kreaturen verstecken sich in tiefen Gräben und Felswänden des Abyss. Viele von ihnen finden sich aber auch im Gefolge dämonischer Fürsten, denen sie als Fußtruppen im endlosen Krieg ihrer Ebene dienen.",
      "Blutdurst. Bulezaus lechzen nach Gewalt. Ihre Bereitschaft, zu töten und zu sterben, macht sie zu geeigneten Kämpfern in den Armeen dämonischer Fürsten. Stellt sich kein größerer und stärkerer Dämon dazwischen, sammeln sich Bulezaus zu großen Gruppen und bekämpfen sich gegenseitig, bis sie ein besseres Ziel finden oder von einem mächtigeren Dämon zum Gehorsam gezwungen werden.",
      "Abstoßend. Bulezaus werden von entstellenden Krankheiten geplagt, etwa von verkrusteten Augen, lebendigen Maden in offenen Wunden und dem Geruch von verwesendem Fleisch, der sie überall begleitet."
    ],
    besonderheiten: [
      { name: "Verderbende Präsenz", beschreibung: "Alle nicht-dämonischen Kreaturen, die ihren Zug im Umkreis von 9 m vom Bulezau beginnen, müssen einen Konstitutionsrettungswurf gegen SG 13 ablegen. Misslingt der Wurf, erleidet die Kreatur 1W6 nekrotischen Schaden plus 1 nekrotischen Schaden für jeden Bulezau, der sich im Umkreis von 9 m zu dieser Kreatur befindet." },
      { name: "Sprung aus dem Stand", beschreibung: "Der Weitsprung des Bulezaus beträgt bis zu 6 m, sein Hochsprung bis zu 3 m. Der Bulezau muss dafür keinen Anlauf nehmen." },
      { name: "Standfest", beschreibung: "Der Bulezau erhält einen Vorteil bei Stärke- und Geschicklichkeitsrettungswürfen gegen Effekte, die ihn auf den Boden werfen würden." }
    ],
    aktionen: [
      { name: "Stachelschwanz", beschreibung: "Nahkampf Waffenangriff: +4 zum Treffen, Reichweite 1,50 m, eine Kreatur. Treffer: 8 (1W12+2) Stichschaden. Ist das Ziel eine Kreatur, muss diese einen Konstitutionsrettungswurf gegen SG 13 gegen Krankheit ablegen. Misslingt der Wurf, wird das Ziel vergiftet, bis die Krankheit endet. Solange die Krankheit anhält, wird das Ziel von eiternden Geschwüren geplagt, hustet Fliegen und wirft verwesende Haut ab. Das Ziel muss den Rettungswurf alle 24 Stunden wiederholen. Bei einem erfolgreichen Rettungswurf ist die Krankheit geheilt. Misslingt der Wurf, sinken die maximalen Trefferpunkte des Ziels um 4 (1W8). Sinken die maximalen Trefferpunkte auf 0, stirbt das Ziel." }
    ],
