      "Canoloths ziehen es vor, Verträge zur Bewachung von Schätzen und wichtigen Orten einzugehen. Sie tun immer genau das, worum sie gebeten werden – niemals mehr, niemals weniger.",
      "Mit ausreichend scharfen Sinnen, um die Aufenthaltsorte von unsichtbaren Kreaturen in der Nähe haargenau festzustellen, reagieren Canoloths unfehlbar auf Bedrohungen für die Dinge in ihrer Obhut. Darüber hinaus geben sie ein magisches Verzerrungsfeld ab, das Kreaturen in ihrer Nähe vom Teleportieren abhält.",
      "Canoloths stellen sich Eindringlingen mit flinker und schrecklicher Macht entgegen. Dabei lassen sie lange, stachelige Zungen vorschnellen, um ihre Gegner zu ergreifen und an sich heranzuziehen. Was als nächstes passiert, hängt vom Vertrag ab. Solange er nicht zu töten instruiert ist, hält der Canoloth seinen Gefangenen einfach nur fest, aber wenn er den Befehl dazu hat, reißt er seine Beute in Stücke."
