    schadensresistenzen: ["Blitz", "Feuer", "Kälte"],
    schadensimmunitaeten: ["Gift", "Hieb-, Stich- und Wuchtschaden aus nicht-magischen Angriffen"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Verängstigt", "Vergiftet"],
    sinne: ["Wahre Sicht 36 m"],
    passiveWahrnehmung: 29,
    sprachen: ["Alle", "Telepathie 36 m"],
    umgebung: ["Andere Ebenen", "Gewässer"],
    bild: "assets/images/monster/foliant/demogorgon.png",
    beschreibung: [
      "Als Prinz der Dämonen, die Zischende Bestie und Meister der Strudelnden Tiefen ist Demogorgon die Verkörperung von Chaos, Wahnsinn und Zerstörung. Er strebt danach, alles, was gut ist, zu verderben und die Ordnung im Multiversum zu untergraben, damit er sehen kann, wie alles heulend in die unendlichen Tiefen des Abyss gezerrt wird.",
      "Der Dämonenfürst ist eine Mischung verschiedener Gestalten, mit einem Echsenunterkörper und klauenbewehrten Füßen mit Schwimmhäuten. Tentakel mit Saugnäpfen sprießen aus den Schultern seines großen, affenartigen Torsos, welcher von zwei abscheulichen Affenköpfen namens Aameul und Hathradiah gekrönt wird, beide gleichermaßen wahnsinnig. Ihr Blick erzeugt Wahnsinn und Verwirrung in jedem, der sich ihm entgegenstellt.",
      "Alle Gefolgsleute des Prinzen der Dämonen werden früher oder später wahnsinnig. Demogorgons Hort Abysm liegt auf einer Schicht des Abyss, die als das Klaffende Maul bekannt ist – ein Ort des Wahnsinns und der Dualität, teils über Wasser in zwei schlangenartigen Türmen, teils tief unter Wasser in kalten und verdunkelten Kavernen."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für Demogorgon ist Charisma (Zauberrettungswurf-SG 23). Er kann die folgenden Zauber angeboren wirken, ohne dass Materialkomponenten notwendig sind. Beliebig oft: Mächtiges Trugbild, Magie entdecken. 3/Tag: Furcht, Magie bannen, Telekinese. 1/Tag: Schwachsinn, Trugbild projizieren." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn Demogorgon einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn dennoch zu schaffen." },
      { name: "Magische Resistenz", beschreibung: "Demogorgon hat einen Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe Demogorgons sind magisch." },
      { name: "Zwei Köpfe", beschreibung: "Demogorgon hat einen Vorteil bei Rettungswürfen gegen die Zustände betäubt, bewusstlos, blind und taub." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Demogorgon führt zwei Tentakel-Angriffe durch." },
      { name: "Tentakel", beschreibung: "Nahkampf Waffenangriff: +17 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 28 (3W12+9) Wuchtschaden. Falls das Ziel eine Kreatur ist, muss ihm ein Konstitutionsrettungswurf gegen SG 23 gelingen, sonst wird sein Trefferpunktemaximum um den Betrag des erlittenen Schadens reduziert. Diese Reduktion hält an, bis das Ziel eine lange Rast beendet. Das Ziel stirbt, falls sein Trefferpunktemaximum auf 0 reduziert wird." },
      { name: "Blick", beschreibung: "Demogorgon richtet seinen magischen Blick auf eine Kreatur, die er innerhalb von 36 m sehen kann. Das Ziel muss einen Weisheitsrettungswurf gegen SG 23 ablegen. Solange das Ziel nicht kampfunfähig ist, kann es seine Augen abwenden, um den Blick zu vermeiden und den Rettungswurf automatisch zu schaffen. Falls das Ziel ihn danach ansieht, muss es augenblicklich den Rettungswurf ablegen. Misslingt der Rettungswurf, erleidet das Ziel einen der folgenden Effekte nach Demogorgons Wahl: (1) Betörender Blick – das Ziel erleidet den Zustand betäubt bis zum Beginn von Demogorgons nächstem Zug oder bis Demogorgon außer Sicht ist. (2) Hypnotischer Blick – das Ziel wird bezaubert bis zum Beginn von Demogorgons nächstem Zug; Demogorgon bestimmt Aktionen, Reaktionen und Bewegung des Ziels. Da dieser Blick beide Köpfe erfordert, kann Demogorgon seine legendäre Aktion In den Wahnsinn treibender Blick erst zu Beginn seines nächsten Zugs wieder nutzen. (3) Irrsinnsblick – das Ziel erleidet den Effekt des Zaubers Verwirrung ohne Rettungswurf bis zum Beginn von Demogorgons nächstem Zug; keine Konzentration nötig." }
    ],
    bonusaktionen: [], reaktionen: [],
