    bild: "assets/images/monster/foliant/der_einsame.png",
    beschreibung: [
      "Der Kummer der Isolation quält viele Kreaturen, die im Shadowfell lauern, aber das Bedürfnis nach Gesellschaft wird niemals dramatischer manifestiert als in den Einsamen. Wenn diese Kummergeschworenen andere Kreaturen bemerken, verspüren sie das brennende Bedürfnis nach Interaktion, und so schießen sie ihre harpunenartigen Arme ab, um ihre Opfer zu sich zu zerren.",
      "Die Kummergeschworenen verkörpern die Gestalten des Leids, die in der schattigen Landschaft des Shadowfell verwurzelt sind. Den negativen Emotionen nachzugeben, die sie repräsentieren, lässt diese Wesenheiten nur tödlicher werden."
    ],
    besonderheiten: [
      { name: "Psychisches Aussaugen", beschreibung: "Zu Beginn jedes Zugs des Einsamen muss jeder Kreatur, die sich innerhalb von 1,50 m um ihn herum befindet, ein Weisheitsrettungswurf gegen SG 15 gelingen, oder sie erleidet 10 (3W6) psychischen Schaden." },
      { name: "Gedeiht in Gesellschaft", beschreibung: "Der Einsame hat einen Vorteil bei Angriffswürfen, während er sich innerhalb von 9 m von mindestens zwei anderen Kreaturen befindet. Ansonsten hat er einen Nachteil bei Angriffswürfen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Einsame führt einen Harpunenarm-Angriff aus und benutzt Kummervolle Umarmung." },
      { name: "Harpunenarm", beschreibung: "Nahkampf Waffenangriff: +7 zum Treffen, Reichweite 18 m, ein Ziel. Treffer: 21 (4W8 + 3) Stichschaden, und das Ziel wird gepackt (SG 15 zum Entkommen), wenn es eine große oder kleinere Kreatur ist. Der Einsame hat zwei Harpunenarme und kann bis zu zwei Kreaturen gleichzeitig packen." },
      { name: "Kummervolle Umarmung", beschreibung: "Jede Kreatur, die vom Einsamen gepackt wird, muss einen Weisheitsrettungswurf gegen SG 15 ablegen. Bei einem misslungenen Rettungswurf erleidet eine Kreatur 18 (4W8) psychischen Schaden, oder die Hälfte bei einem gelungenen. In beiden Fällen zerrt der Einsame jede Kreatur, die er gepackt hat, bis zu 10 m in gerader Linie zu sich hin." }
    ],
    bonusaktionen: [], reaktionen: [], legendaere_aktionen: null,
    source: "Foliant der Feinde"
