      { name: "Wachsender Zorn", beschreibung: "Wenn eine andere Kreatur dem Wütenden Schaden zufügt, hat der Wütende einen Vorteil bei seinen Angriffswürfen bis zum Ende seines nächsten Zugs, und das erste Mal, wenn er bei seinem nächsten Zug mit einem Haken-Angriff trifft, erleidet das Ziel des Angriffs zusätzlich 19 (3W12) psychischen Schaden. Bei seinem Zug hat der Wütende einen Nachteil bei seinen Angriffswürfen, wenn keine andere Kreatur ihm seit dem Ende seines letzten Zugs Schaden zugefügt hat." }
