      { name: "Zauberwirken", beschreibung: "Der Derro-Wissende ist ein Zauberwirker der 5. Stufe. Sein Attribut zum Zauberwirken ist Charisma (Zauberrettungswurf-SG 12, +4 zum Treffen mit Zauberangriffen). Der Derro-Wissende hat die folgenden Magierzaubersprüche vorbereitet: Zaubertricks (beliebig oft): Botschaft, Magierhand, Kältestrahl, Säurespritzer, Taschenspielerei. 1. Grad (4 Plätze): Brennende Hände, Chromatische Kugel, Schlaf. 2. Grad (3 Plätze): Spinnenklettern, Unsichtbarkeit. 3. Grad (2 Plätze): Blitz." }
