    fertigkeiten: { "Arkane Kunde": 9, "Heimlichkeit": 8, "Naturkunde": 9, "Wahrnehmung": 7 },
    schadensresistenzen: ["Gift"],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Verängstigt", "Vergiftet"],
    sinne: ["Blindsicht 3 m", "Dunkelsicht 36 m"],
    passiveWahrnehmung: 17,
    sprachen: ["Elfisch", "Gemeinsprache der Unterreiche", "kann mit Spinnen sprechen"],
    umgebung: ["Unterirdisch"],
    bild: "assets/images/monster/foliant/drow_arachnomant.png",
    beschreibung: [
      "Drow-Zauberwirker, die danach streben, sich selbst vollkommen der Spinnenkönigin zu widmen, beschreiten manchmal den dunklen Pfad des Arachnomanten. Indem sie Lolth Körper und Seele hingeben, erlangen sie enorme Macht und eine übernatürliche Verbindung zu den uralten Spinnen der Dämonennetzgruben, und sie kanalisieren Magie aus diesem furchtbaren Ort."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Drow-Arachnomant ist Charisma (Zauberrettungswurf-SG 16). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Tanzende Lichter. Jeweils 1/Tag: Dunkelheit, Feenfeuer, Schweben (nur auf sich selbst)." },
      { name: "Empfindlich gegen Sonnenlicht", beschreibung: "Solange sich der Drow im Sonnenlicht befindet, erleidet er einen Nachteil bei Angriffswürfen sowie bei Würfen auf Weisheit (Wahrnehmung), die auf Sicht beruhen." },
      { name: "Feenblut", beschreibung: "Der Drow hat einen Vorteil bei Rettungswürfen, wenn er bezaubert werden soll, und Magie kann ihn nicht einschläfern." },
      { name: "Form ändern (Aufladung nach kurzer oder langer Rast)", beschreibung: "Der Drow kann eine Bonusaktion verwenden, um sich auf magische Weise in eine Riesenspinne zu verwandeln und verbleibt bis zu 1 Stunde in dieser Form. Er kann als eine Bonusaktion zu seiner wahren Form zurückkehren. Seine Spielwerte, ausgenommen seiner Größe, sind in jeder Gestalt dieselben. Er kann sprechen und Zauber wirken, während er Riesenspinnengestalt angenommen hat. Alle Ausrüstung, die er in humanoider Gestalt bei sich trägt oder hält, verschmilzt mit der Riesenspinnengestalt. Er kann keine dieser Ausrüstungsstücke aktivieren, benutzen, führen oder anderweitig daraus einen Vorteil ziehen. Er kehrt zu seiner humanoiden Gestalt zurück, falls er stirbt." },
      { name: "Netzwandler", beschreibung: "Der Drow ignoriert Bewegungseinschränkungen, die durch Netze ausgelöst werden." },
      { name: "Spinnenklettern", beschreibung: "Der Drow kann an schwierigen Oberflächen klettern, sogar kopfüber an der Decke, ohne einen Attributswurf ablegen zu müssen." },
      { name: "Zauberwirken", beschreibung: "Der Drow ist ein Zauberwirker der 16. Stufe. Sein Attribut zum Zauberwirken ist Charisma (Zauberrettungswurf-SG 16, +8 zum Treffen mit Zauberangriffen). Er erhält seine verbrauchten Zauberplätze zurück, wenn er eine kurze oder lange Rast abschließt. Er kennt die folgenden Hexenmeisterzaubersprüche: Zaubertricks (beliebig oft): Gift versprühen, Kalte Hand, Magierhand, Schauriger Strahl. 1.-5. Grad (3 Zauberplätze des 5. Grades): Dimensionstür, Fliegen, Furcht, Hexenpfeil, Insektenplage, Krone des Wahnsinns, Magie bannen, Monster festhalten, Rieseninsekt, Spinnennetz, Tiere beschwören (nur Spinnen), Unsichtbarkeit, Vampirgriff. Jeweils 1/Tag: Ätherische Gestalten, Böser Blick, Monster beherrschen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Drow führt zwei Giftige Berührung-Angriffe oder zwei Bissangriffe aus. Der erste dieser Angriffe, der in jeder Runde trifft, verursacht zusätzlich 26 (4W12) Giftschaden beim Ziel." },
      { name: "Giftige Berührung (nur humanoide Gestalt)", beschreibung: "Nahkampf Waffenangriff: +8 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 28 (8W6) Giftschaden." },
      { name: "Biss (nur Riesenspinnengestalt)", beschreibung: "Nahkampf Waffenangriff: +7 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 12 (2W8+3) Stichschaden, und das Ziel muss einen Konstitutionsrettungswurf gegen SG 15 ablegen. Bei einem misslungenen Rettungswurf erleidet es 26 (4W12) Giftschaden oder den halben Schaden bei einem gelungenen. Falls das Gift die Trefferpunkte des Ziels auf 0 reduziert, ist das Ziel stabil, erleidet aber 1 Stunde lang den Zustand vergiftet, sogar nachdem es Trefferpunkte zurückerhalten hat. Außerdem erleidet es den Zustand gelähmt, während es auf diese Art vergiftet ist." },
      { name: "Netz (nur Riesenspinnengestalt; Aufladung 5–6)", beschreibung: "Fernkampf Waffenangriff: +8 zum Treffen, Reichweite 9/18 m, ein Ziel. Treffer: Das Ziel wird vom Netz festgesetzt. Als Aktion kann das festgesetzte Ziel einen Stärkewurf gegen SG 15 ablegen. Bei einem Erfolg befreit es sich aus den Netzen. Die Netze können auch angegriffen und zerstört werden (RK 10; TP 5; Anfälligkeit gegen Feuerschaden; Immunität gegen Giftschaden, psychischen Schaden und Wuchtschaden)." }
    ],
    bonusaktionen: [], reaktionen: [], legendaere_aktionen: null,
    source: "Foliant der Feinde"
