    bild: "assets/images/monster/foliant/drow_matronenmutter.png",
    beschreibung: [
      "Am Kopfende jedes Drow-Adelshauses sitzt eine Matronenmutter, eine einflussreiche Priesterin der Lolth, die mit der Ausführung des Willens der Göttin beauftragt ist, während sie ebenfalls die Interessen der Familie voranbringen soll. Matronenmütter verkörpern die Intrigen und den Verrat, die mit der Spinnenkönigin verbunden werden.",
      "Jede hockt in der Mitte eines riesigen konspirativen Netzes, mit Dämonen, Drow, Spinnen und Sklaven, die zwischen ihnen und ihren Feinden in Position gebracht wurden. Obwohl Matronenmütter über große Macht gebieten, hängt diese Macht davon ab, ob sie die Gunst der Spinnenkönigin aufrechterhalten können, und die dunkle Göttin nimmt sich manchmal kapriziös zurück, was sie vorher geschenkt hat."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für die Drow ist Charisma (Zauberrettungswurf-SG 20). Sie kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Tanzende Lichter, Magie entdecken. Jeweils 1/Tag: Dunkelheit, Einflüsterung, Feenfeuer, Gedanken wahrnehmen, Hellsehen, Magie bannen, Schweben (nur selbst)." },
      { name: "Empfindlich gegen Sonnenlicht", beschreibung: "Solange sich die Drow im Sonnenlicht befindet, erleidet sie einen Nachteil bei Angriffswürfen sowie bei Würfen auf Weisheit (Wahrnehmung), die auf Sicht beruhen." },
      { name: "Feenblut", beschreibung: "Die Drow hat einen Vorteil bei Rettungswürfen, wenn sie bezaubert werden soll, und Magie kann sie nicht einschläfern." },
      { name: "Lolths launische Gunst", beschreibung: "Als eine Bonusaktion kann die Matrone einem Verbündeten, den sie innerhalb von 9 m um sich herum sehen kann, den Segen der Spinnenkönigin spenden. Der Verbündete erleidet 7 (2W6) psychischen Schaden, hat aber einen Vorteil beim nächsten Angriffswurf, den er vor dem Ende seines nächsten Zugs durchführt." },
      { name: "Magieresistenz", beschreibung: "Die Drow hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." },
      { name: "Zauberwirken", beschreibung: "Die Drow ist eine Zauberwirkerin der 20. Stufe. Ihr Attribut zum Zauberwirken ist Weisheit (Zauberrettungswurf-SG 19, +11 zum Treffen mit Zauberangriffen). Sie hat die folgenden Klerikerzaubersprüche vorbereitet: Zaubertricks (beliebig oft): Ausbessern, Göttliche Führung, Heilige Flamme, Resistenz, Thaumaturgie. 1. Grad (4 Plätze): Befehl, Lenkendes Geschoss, Verderben, Wunden heilen. 2. Grad (3 Plätze): Person festhalten, Stille, Waffe des Glaubens. 3. Grad (3 Plätze): Fluch, Hellsehen, Magie bannen, Schutzgeister. 4. Grad (3 Plätze): Bewegungsfreiheit, Hüter des Glaubens, Verbannung, Todesschutz. 5. Grad (3 Plätze): Ansteckung, Flammenschlag, Geas, Massen-Wunden heilen. 6. Grad (2 Plätze): Klingenbarriere, Leid. 7. Grad (2 Plätze): Ebenenwechsel, Göttliches Wort. 8. Grad (1 Platz): Heilige Aura. 9. Grad (1 Platz): Tor." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Matronenmutter führt zwei Dämonenstecken-Angriffe oder drei Tentakelzepter-Angriffe aus." },
      { name: "Dämonenstecken", beschreibung: "Nahkampf Waffenangriff: +10 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 7 (1W6+4) Wuchtschaden, oder 8 (1W8+4) Hiebschaden, wenn er mit beiden Händen geführt wird, plus 14 (4W6) psychischer Schaden. Zusätzlich muss dem Ziel ein Weisheitsrettungswurf gegen SG 19 gelingen, sonst wird es 1 Minute lang von der Drow verängstigt. Das verängstigte Ziel kann den Rettungswurf am Ende jedes seiner Züge wiederholen und bei Gelingen den Effekt auf sich selbst beenden." },
      { name: "Tentakelzepter", beschreibung: "Nahkampf Waffenangriff: +9 zum Treffen, Reichweite 4,50 m, ein Ziel. Treffer: 3 (1W6) Wuchtschaden. Falls das Ziel innerhalb eines Zugs dreimal von dem Zepter getroffen wird, muss dem Ziel ein Konstitutionsrettungswurf gegen SG 15 gelingen, sonst erleidet es 1 Minute lang die folgenden Effekte: Die Bewegungsrate des Ziels wird halbiert, es hat einen Nachteil bei Geschicklichkeitsrettungswürfen, und es kann keine Reaktionen benutzen. Darüber hinaus kann es bei jedem seiner Züge entweder eine Aktion oder eine Bonusaktion durchführen, aber nicht beides. Am Ende jedes seiner Züge kann es den Rettungswurf wiederholen und bei Gelingen den Effekt auf sich selbst beenden." },
      { name: "Dämon beschwören (1/Tag)", beschreibung: "Die Drow beschwört auf magische Weise einen Dämonischen Nimrod oder einen Yochlol. Die beschworene Kreatur erscheint in einem unbesetzten Bereich innerhalb von 18 m um ihre Beschwörerin herum und kann keine anderen Dämonen beschwören. Sie verbleibt 10 Minuten lang, bis sie oder ihre Beschwörerin stirbt, oder bis ihre Beschwörerin sie als eine Aktion fortschickt." }
    ],
