      { name: "Zauber wirken (kostet 1–3 Aktionen)", beschreibung: "Die Drow verbraucht einen Zauberplatz, um einen Zauber des 1., 2. oder 3. Grades zu wirken, den sie vorbereitet hat. Dies kostet 1 legendäre Aktion pro Grad des Zaubers." }
