    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Drow ist Charisma (Zauberrettungswurf-SG 18). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Tanzende Lichter. Jeweils 1/Tag: Dunkelheit, Feenfeuer, Schweben (nur auf sich selbst)." },
      { name: "Empfindlich gegen Sonnenlicht", beschreibung: "Solange sich der Drow im Sonnenlicht befindet, erleidet er einen Nachteil bei Angriffswürfen sowie bei Würfen auf Weisheit (Wahrnehmung), die auf Sicht beruhen." },
      { name: "Feenblut", beschreibung: "Der Drow hat einen Vorteil bei Rettungswürfen, wenn er bezaubert werden soll, und Magie kann ihn nicht einschläfern." },
      { name: "Kriegsmagie", beschreibung: "Wenn der Drow seine Aktion nutzt, um einen Zauberspruch zu wirken, kann er als Bonusaktion einen Waffenangriff ausführen." },
      { name: "Zauberwirken", beschreibung: "Der Drow ist ein Zauberwirker der 11. Stufe. Sein Attribut zum Zauberwirken ist Intelligenz (Zauberrettungswurf-SG 18, +10 zum Treffen mit Zauberangriffen). Er hat die folgenden Magierzaubersprüche vorbereitet: Zaubertricks (beliebig oft): Botschaft, Gift versprühen, Kältestrahl, Magierhand, Schockgriff. 1. Grad (4 Plätze): Brennende Hände, Magierrüstung, Magisches Geschoss, Schild. 2. Grad (3 Plätze): Nebelschritt, Unsichtbarkeit, Windstoß, Zerbersten. 3. Grad (3 Plätze): Feuerball, Gegenzauber, Hast. 4. Grad (3 Plätze): Dimensionstür, Otilukes Unverwüstliche Sphäre. 5. Grad (2 Plätze): Kältekegel. 6. Grad (1 Platz): Kugelblitz." }
    ],
