      { name: "Handarmbrust", beschreibung: "Fernkampf Waffenangriff: +11 zum Treffen, Reichweite 9/36 m, ein Ziel. Treffer: 8 (1W6+5) Stichschaden, und dem Ziel muss ein Konstitutionsrettungswurf gegen SG 13 gelingen, sonst erleidet es 1 Stunde lang den Zustand vergiftet. Falls der Rettungswurf um 5 oder mehr Punkte misslingt, erleidet das Ziel zusätzlich den Zustand bewusstlos, solange es auf diese Weise vergiftet ist. Das Ziel erlangt das Bewusstsein zurück, falls es Schaden erleidet oder falls eine andere Kreatur eine Aktion aufwendet, um es zu schütteln." }
