    bild: "assets/images/monster/foliant/duergar-gedankenmeister.png",
    beschreibung: ["Die gefürchteten Duergar-Gedankenmeister operieren für gewöhnlich als Spione, sowohl innerhalb eines Duergar-Bollwerks, als auch darüber hinaus. Ihre psionisch gesteigerten Fertigkeiten befähigen sie dazu, mit Leichtigkeit Illusionen zu durchschauen und auf Miniaturgröße zu schrumpfen, um ihre Ziele auszuspionieren."],
    besonderheiten: [
      { name: "Duergar-Widerstandskraft", beschreibung: "Der Duergar hat einen Vorteil bei Rettungswürfen gegen Gifte, Zauber und Illusionen und ebenfalls bei Würfen, um den Zuständen verzaubert oder gelähmt zu widerstehen." },
      { name: "Empfindlich gegen Sonnenlicht", beschreibung: "Solange sich der Duergar im Sonnenlicht befindet, erleidet er einen Nachteil bei Angriffswürfen sowie bei Würfen auf Weisheit (Wahrnehmung), die auf Sicht beruhen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Duergar führt zwei Nahkampfangriffe durch. Er kann einen dieser Angriffe durch eine Nutzung von Gedankenherrschaft ersetzen." },
      { name: "Gedankengiftdolch", beschreibung: "Nahkampf Waffenangriff: +5 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 5 (1W4 + 3) Stichschaden und 10 (3W6) psychischer Schaden, oder 1 Stichschaden und 14 (4W6) psychischer Schaden, während er verkleinert ist." },
      { name: "Unsichtbarkeit (Aufladung 4–6)", beschreibung: "Der Duergar wird auf magische Weise bis zu 1 Stunde lang unsichtbar, bis er angreift, einen Zauber wirkt, seine Aktion Verkleinern benutzt oder seine Konzentration unterbrochen wird (als würde er sich auf einen Zauberspruch konzentrieren). Alle Ausrüstungsgegenstände, die der Duergar trägt oder in der Hand hält, werden mit ihm unsichtbar." },
      { name: "Gedankenherrschaft", beschreibung: "Der Duergar wählt eine Kreatur als Ziel aus, die er innerhalb von 18 m um sich herum sehen kann. Dem Ziel muss ein Intelligenzrettungswurf gegen SG 12 gelingen, sonst zwingt der Duergar es dazu, seine Reaktion dazu zu benutzen, entweder einen Waffenangriff gegen eine andere Kreatur auszuführen, die der Duergar sehen kann, oder sich bis zu 3 m weit in eine Richtung nach Wahl des Duergar zu bewegen. Kreaturen, die nicht bezaubert werden können, sind immun gegen diesen Effekt." },
      { name: "Verkleinern (Aufladung nach einer kurzen oder langen Rast)", beschreibung: "Der Duergar verkleinert 1 Minute lang seine Größe auf magische Weise, zusammen mit allem, was er trägt oder in der Hand hält. Während er verkleinert ist, ist der Duergar winzig, verringert seinen Waffenschaden auf 1 und würfelt Angriffswürfe, Attributswürfe und Rettungswürfe mit Nachteil, falls sie Stärke benutzen. Er erhält einen Bonus von +5 bei allen Würfen auf Geschicklichkeit (Heimlichkeit) und einen Bonus von +5 auf seine RK. Er kann ebenfalls eine Bonusaktion bei jedem seiner Züge ausführen, um die Aktion Verstecken zu benutzen." }
    ],
