    beschreibung: ["Ein Duergar-Schreier ist ein Konstrukt, das Schallenergie verwendet, um Stein zu Staub zu zermahlen. Duergar, die beschuldigt werden, Tratsch zu verbreiten oder etwas gegen ihre Vorgesetzten im Schilde zu führen, werden in einem dieser Geräte eingesperrt, ihr Bart wird geschoren und ihre anhaltende Agonie in psionische Energie kanalisiert, welche den Schreier antreibt."],
