      { name: "Schallschrei", beschreibung: "Der Schreier gibt in einem Würfel von 4,50 m Kantenlänge destruktive Energie von sich. Jeder Kreatur in diesem Bereich muss ein Stärkerettungswurf gegen SG 11 gelingen, sonst erleidet sie 7 (2W6) Schallschaden und den Zustand liegend." }
