      { name: "Seelenklinge erschaffen", beschreibung: "Als eine Bonusaktion kann der Duergar eine sichtbare Klinge aus psionischer Energie von der Länge eines Kurzschwertes erschaffen. Die Waffe erscheint in der Hand des Duergar und verschwindet, falls sie den Griff des Duergar verlässt, oder falls der Duergar getötet oder kampfunfähig gemacht wird." }
