    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 10,
    sprachen: ["Versteht eine Sprache seines Herstellers, kann aber nicht sprechen"],
    umgebung: ["Unterirdisch", "Ruinen"],
    bild: "assets/images/monster/foliant/eichenballiste.png",
    beschreibung: [
      "Eichenballisten sind ganz außergewöhnliche Vertreter ihrer Art, die auf große Entfernungen schießen können. Abgefeuerte Bolzen können das Fleisch der Feinde zerreißen, ihre Rüstung zerstören oder die Feinde mit einer Nahkampfvorrichtung in eine Falle treiben. Auf kurze Entfernung können sie sogar explodieren."
    ],
    besonderheiten: [
      { name: "Magische Resistenz", beschreibung: "Eichenballisten haben einen Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Eichenballiste führt wahlweise zwei Bolzenangriffe oder einen Bolzen- und einen Harpunenangriff aus." },
      { name: "Bolzenangriff", beschreibung: "Nahkampf- oder Fernkampf-Waffenangriff: +7 zum Treffen, Reichweite 1,50 m oder 30/120 m, eine Kreatur. Treffer: 15 (2W10+4) Stichschaden." },
      { name: "Harpune", beschreibung: "Fernkampf-Waffenangriff: +7 zum Treffen, Reichweite 15/60 m, ein Ziel. Treffer: 9 (1W10+4) Stichschaden, das Ziel wird gepackt (Befreiung SG 12). Die Bewegungsrate einer gepackten Kreatur wird dadurch nicht reduziert, sie kann sich jedoch nur in Richtungen bewegen, die sie der Eichenballiste näher bringen. Wenn die Kreatur versucht, sich zu befreien, erleidet sie 5 (1W10) Hiebschaden, unabhängig davon, ob der Versuch erfolgreich ist. Die Eichenballiste kann als Bonusaktion die gepackte Kreatur 6 m heranziehen. Die Eichenballiste kann nur eine Kreatur gleichzeitig packen." },
      { name: "Explosiver Bolzen (Aufladung 5–6)", beschreibung: "Die Eichenballiste schießt einen explosiven Bolzen auf einen Punkt innerhalb von 36 m, den sie sehen kann. Jede Kreatur im Umkreis von 6 m um den Auftreffpunkt muss einen Geschicklichkeitsrettungswurf gegen SG 15 ablegen. Misslingt der Rettungswurf, nimmt die jeweilige Kreatur 17 (5W6) Feuerschaden. Bei einem erfolgreichen Rettungswurf wird der Schaden halbiert." }
    ],
    bonusaktionen: [],
