      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,50 m, eine Kreatur. Treffer: 6 (1W6+3) Stichschaden. Ist das Ziel eine Kreatur, muss diese einen Konstitutionsrettungswurf gegen SG 13 ablegen. Misslingt der Wurf, erleidet das Ziel einen zufälligen Gifteffekt (W3): 1. Giftschaden — Das Ziel erleidet 13 (3W8) Giftschaden. 2. Verwirrung — Bei ihrem nächsten Zug muss das Ziel einen Angriffswurf gegen eine zufällige Kreatur ausführen, die es im Umkreis von 9 m sehen kann. Dazu benutzt es die Waffe, die es gerade in der Hand hält; wenn nötig führt es zuvor eine Bewegungsaktion aus. Hält das Ziel keine Waffe, führt es einen unbewaffneten Angriff aus. Ist in einem Umkreis von 9 m keine Kreatur sichtbar, führt es eine Spurt-Aktion zur nächsten Kreatur aus. 3. Lähmung — Bis zum Ende seines nächsten Zugs ist das Ziel gelähmt." }
