    bild: "assets/images/monster/foliant/frostsalamander.png",
    beschreibung: [
      "Frostsalamander sind in der Ebene des Eises heimisch, auch das Frostfell genannt, welche zwischen der Ebene der Luft und der Ebene des Wassers ruht. Frostsalamander lieben es besonders, warmblütige Kreaturen zu jagen, und reisen manchmal zu eisigen Gefilden auf der Materiellen Ebene, indem sie durch planare Tore wandern.",
      "Verschlinger der Wärme. Der aggressive Appetit der Frostsalamander auf jegliche Wärmequelle bringt sie dazu, Siedlungen anzugreifen. Sie könnten das Feuer einer Schmiede oder ein Lagerfeuer mit einer großen, schmackhaften Mahlzeit verwechseln. Manchmal wagen sich Azer ins Frostfell vor, wo sie große Feuer benutzen, um Frostsalamander in Fallen zu locken und ihre Häute und Reißzähne für die Verarbeitung zu Waffen und Rüstungen zu sammeln.",
      "Trügerische Zuflucht. Frostsalamander bevorzugen es, sich ins Eis zu graben, und erschaffen weitläufige Netzwerke aus Eishöhlen. Ein Frostsalamander, der eine Weile lang in einem Bau lebt, gräbt genügend Raum, um einer kleinen Armee zu erlauben, darin zu kampieren. Unerfahrene Reisende, die über diese Höhlen stolpern, sehen sie als einen willkommenen Unterschlupf – obwohl sie alles andere sind."
    ],
