      { name: "Eisiger Atem (Wiederaufladung 6)", beschreibung: "Der Salamander atmet frostigen Wind in einem Kegel von 18 m. Jede Kreatur in diesem Bereich muss einen Konstitutionsrettungswurf gegen SG 17 ablegen. Bei einem misslungenen Rettungswurf erleidet sie 44 (8W10) Kälteschaden, oder den halben Schaden bei einem gelungenen." }
