    attribute: { STR: 14, DEX: 16, CON: 16, INT: 18, WIS: 11, CHA: 18 },
    rettungswuerfe: {},
    fertigkeiten: { "Täuschen": 8, "Überzeugen": 8 },
    schadensresistenzen: ["Hieb-, Stich- und Wuchtschaden durch nicht-magische Angriffe"],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 10,
    sprachen: ["Elfisch", "Gemeinsprache", "Sylvanisch"],
    umgebung: ["Feenwildnis"],
    bild: "assets/images/monster/foliant/fruehlingseladrin.png",
    beschreibung: [
      "Die Eladrin hausen in der üppig grünen Pracht des Feywild. Sie sind mit den auf der Materiellen Ebene zu findenden Elfen verwandt und ähneln ihnen sowohl in ihrer Liebe zur Schönheit als auch im Wert, den sie persönlicher Freiheit zumessen. Doch wo andere Elfen ihre wilden Impulse zügeln können, sind Eladrin Kreaturen, die von ihren Emotionen beherrscht werden – und aufgrund ihrer einzigartigen magischen Natur machen sie körperliche Veränderungen durch, die den Änderungen ihres Temperaments entsprechen.",
      "Kreaturen der Leidenschaft. Die Magie, welche die Eladrin durchströmt, reagiert auf ihren emotionalen Zustand, indem sie sie in verschiedene jahreszeitliche Aspekte verwandelt, mit Verhaltensweisen und Fähigkeiten, die sich mit ihren Gestalten verändern. Manche Eladrin können jahrelang in einem bestimmten Aspekt verbleiben, während andere jede Woche das emotionale Spektrum durchlaufen. Wann immer ein Eladrin eine lange Rast beendet, kann er sich mit einer anderen Jahreszeit assoziieren und dabei die Spielwerte der neuen Jahreszeit annehmen.",
      "Mit ihren von Freude erfüllten Herzen tollen Frühlingseladrin durch ihre Waldreiche, und ihre Gesänge und ihr Lachen erfüllen die Luft. Die verspielten Eladrin betören andere Kreaturen, um sie mit der Freude des Frühlings zu erfüllen. Ihre Kapriolen können andere Kreaturen in Gefahr bringen und ihnen Scherereien bereiten."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Eladrin ist Charisma (Zauberrettungswurf-SG 16). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Person bezaubern, Tashas fürchterlicher Lachanfall. Jeweils 3/Tag: Einflüsterung, Fesseln, Verwirrung. Jeweils 1/Tag: Ottos unwiderstehlicher Tanz, Scheingelände." },
      { name: "Feenschritt (Aufladung 4–6)", beschreibung: "Als Bonusaktion kann der Eladrin sich bis zu 9 m weit in einen unbesetzten Bereich teleportieren, den er sehen kann." },
      { name: "Fröhliche Präsenz", beschreibung: "Jede Kreatur, die kein Eladrin ist und ihren Zug innerhalb von 18 m um den Eladrin herum beginnt, muss einen Weisheitsrettungswurf gegen SG 16 ablegen. Bei einem misslungenen Rettungswurf wird die Kreatur 1 Minute lang vom Eladrin bezaubert. Bei einem gelungenen Rettungswurf wird die Kreatur 24 Stunden lang immun gegen die Fröhliche Präsenz jedes Eladrin. Wann immer der Eladrin der bezauberten Kreatur Schaden zufügt, kann die Kreatur den Rettungswurf wiederholen und bei Gelingen den Effekt auf sich selbst beenden." },
      { name: "Magieresistenz", beschreibung: "Der Eladrin hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Eladrin führt zwei Waffenangriffe durch. Er kann anstelle eines dieser Angriffe einen Zauberspruch wirken." },
      { name: "Langschwert", beschreibung: "Nahkampf Waffenangriff: +6 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 6 (1W8 + 2) Hiebschaden, oder 7 (1W10 + 2) Hiebschaden, falls es mit beiden Händen geführt wird, plus 4 (1W8) psychischer Schaden." },
      { name: "Langbogen", beschreibung: "Fernkampf Waffenangriff: +7 zum Treffen, Reichweite 45/180 m, ein Ziel. Treffer: 7 (1W8 + 3) Stichschaden plus 4 (1W8) psychischer Schaden." }
    ],
