    tp: 300,
    tp_wuerfel: "24W12+144",
    bewegung: { "Gehen": "9 m", "Fliegen": "15 m" },
    attribute: { STR: 29, DEX: 17, CON: 22, INT: 19, WIS: 16, CHA: 23 },
    rettungswuerfe: { GES: 10, KON: 13, WEI: 10, CHA: 13 },
    fertigkeiten: { "Einschüchtern": 13, "Überzeugen": 13, "Wahrnehmung": 10 },
    schadensresistenzen: ["Hieb-, Stich- und Wuchtschaden durch nicht-magische Angriffe, der nicht von versilberten Waffen verursacht wird"],
    schadensimmunitaeten: ["Feuer", "Gift", "Kälte"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Verängstigt", "Vergiftet"],
    sinne: ["Wahre Sicht 36 m"],
    passiveWahrnehmung: 20,
    sprachen: ["alle", "Telepathie 36 m"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/geryon.png",
    beschreibung: [
      "Geryon steckt in einem endlosen Kampf mit Levistus um die Kontrolle über Stygia fest. Derzeit besetzt Geryon eine merkwürdige Position in der infernalen Hierarchie: Obwohl Levistus immer noch die Herrschaft über Stygia beansprucht, wurde er auf Anordnung von Asmodeus in einem enormen Eisblock gefangengesetzt. Geryon seinerseits zieht seine Gefolgsleute zusammen und strebt danach, die Mittel zu finden, um seinen verhassten Rivalen zu ersetzen.",
      "Unter den Erzteufeln sind Geryon und Zariel besonders für ihr kriegerisches Talent bekannt. Geryon ist ein wilder Jäger und unerbittlicher Fährtensucher. Andere Teufel befehligen Legionen und gebieten ihren Gefolgsleuten, ihre Feinde zu bekämpfen. Geryon liebt das Gefühl, wenn Fleisch und Stahl von seinen Klauen zerrissen werden und den Geschmack des Bluts seiner Feinde.",
      "Geryon hat kürzlich seine uralte Festung Kaltstahl zurückerobert, einen weitläufigen Komplex, der sich im Zentrum Stygias aus dem allgegenwärtigen Schnee und Eis erhebt."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für Geryon ist Charisma (Zauberrettungswurf-SG 21, +13 zum Treffen mit Zauberangriffen). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Einflüsterung, Eissturm, Eiswand, Geas, Gegenstand aufspüren, Gestalt verändern (kann mittelgroß werden, wenn er sein Erscheinungsbild verändert), Magie entdecken, Unsichtbarkeit (nur auf sich selbst). Jeweils 1/Tag: Göttliches Wort, Symbol (nur Schmerz)." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn Geryon einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn zu schaffen." },
      { name: "Magieresistenz", beschreibung: "Geryon hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe Geryons sind magisch." },
      { name: "Regeneration", beschreibung: "Geryon erhält zu Beginn seines Zugs 20 Trefferpunkte zurück. Falls er gleißenden Schaden erleidet, funktioniert dieses Merkmal zu Beginn seines nächsten Zugs nicht. Geryon stirbt nur, falls er seinen Zug mit 0 Trefferpunkten beginnt und nicht regeneriert." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Geryon führt zwei Nahkampfangriffe durch: einen mit seinen Klauen und einen mit seinem Stachel." },
      { name: "Klauen", beschreibung: "Nahkampf Waffenangriff: +16 zum Treffen, Reichweite 4,50 m, ein Ziel. Treffer: 23 (4W6+9) Hiebschaden. Falls das Ziel groß oder kleiner ist, erleidet es die Zustände gepackt (SG 24) und festgesetzt, bis der Zustand gepackt endet. Geryon kann nur eine Kreatur gleichzeitig packen. Falls das Ziel bereits von Geryon gepackt ist, erleidet es zusätzliche 27 (6W8) Hiebschaden." },
      { name: "Stachel", beschreibung: "Nahkampf Waffenangriff: +16 zum Treffen, Reichweite 6 m, ein Ziel. Treffer: 14 (2W4+9) Stichschaden, und dem Ziel muss ein Konstitutionsrettungswurf gegen SG 21 gelingen, sonst erleidet es 13 (2W12) Giftschaden und den Zustand vergiftet, bis es eine kurze oder lange Rast beendet. Das Trefferpunktemaximum des Ziels wird um den halben Betrag des Giftschadens reduziert, den es erleidet. Falls sein Trefferpunktemaximum auf 0 fällt, stirbt es. Diese Reduktion hält an, bis der Zustand vergiftet entfernt wird." },
      { name: "Teleportieren", beschreibung: "Geryon teleportiert sich zusammen mit aller Ausrüstung, die er trägt oder hält, auf magische Weise bis zu 36 m weit in einen nicht besetzten Bereich, den er sehen kann." },
      { name: "Ins Horn stoßen (Variante, 1/Tag)", beschreibung: "Geryon bläst in sein Horn, was 5W4 Minotauren in unbesetzten Bereichen seiner Wahl erscheinen lässt, die er innerhalb von 180 m um sich herum sehen kann. Die Minotauren würfeln ihre Initiative aus, wenn sie erscheinen. Sie bleiben, bis sie sterben oder Geryon eine Aktion benutzt, um eine beliebige Anzahl von ihnen wegzuschicken." }
    ],
    bonusaktionen: [],
    reaktionen: [],
    legendaere_aktionen: [
      { name: "Infernales Starren", beschreibung: "Geryon wählt eine Kreatur als Ziel aus, die er innerhalb von 18 m um sich herum sehen kann. Falls das Ziel Geryon sehen kann, muss der Kreatur ein Weisheitsrettungswurf gegen SG 23 gelingen, sonst erleidet sie bis zum Ende ihres nächsten Zugs den Zustand verängstigt vor Geryon." },
      { name: "Flinker Stich (kostet 2 Aktionen)", beschreibung: "Geryon greift mit seinem Stachel an." },
      { name: "Teleportieren", beschreibung: "Geryon benutzt seine Aktion Teleportieren." }
    ],
    hortaktionen: {
      beschreibung: "Bei Initiative 20 (wobei er alle Initiative-Gleichstände verliert) kann Geryon eine Hortaktion ausführen, um einen der folgenden Effekte auszulösen; er kann denselben Effekt nicht in zwei aufeinanderfolgenden Runden benutzen:",
      aktionen: [
        "Geryon lässt an einem Punkt, den er innerhalb von 36 m um sich herum sehen kann, einen kalten Luftstoß aus dem Boden brechen. Die Kälte füllt einen Würfel mit 3 m Kantenlänge und der Mitte an diesem Punkt aus. Jeder Kreatur in diesem Bereich muss ein Konstitutionsrettungswurf gegen SG 21 gelingen, sonst erleidet sie 28 (8W6) Kälteschaden.",
        "Geryon wählt eine Kreatur als Ziel aus, die er innerhalb von 18 m um sich herum sehen kann. Dem Ziel muss ein Weisheitsrettungswurf gegen SG 21 gelingen, sonst erleidet es 1 Minute lang den Zustand festgesetzt. Das Ziel kann den Effekt auf sich selbst beenden, falls es einem oder mehreren seiner Verbündeten irgendwelchen Schaden zufügt.",
        "Geryon wirkt den Zauber Verbannung."
      ]
    },
    regionale_effekte: {
      beschreibung: "Die Region, die Geryons Hort enthält, wird von seiner Magie verzerrt, was einen oder mehrere der folgenden Effekte verursacht:",
      effekte: [
        "Intelligente Kreaturen, die sich innerhalb von 1,50 km um den Hort herum aufhalten, sehen regelmäßig schimmernde Portale, die an Orte führen, die sie für sicher erachten. Durch eines der Portale zu treten, setzt einen Reisenden immer irgendwo in Stygia ab.",
        "Eiskalte starke Winde heulen in einem Bereich von 1,50 km um den Hort herum.",
        "Geheul und Schreie erfüllen die Luft innerhalb von 1,50 km um den Hort herum. Jeder Kreatur, die eine kurze oder lange Rast in diesem Bereich beendet, muss ein Weisheitsrettungswurf gegen SG 21 gelingen, sonst zieht sie keinen Nutzen aus der Rast. Falls Geryon stirbt, verblassen diese Effekte im Lauf von 1W10 Tagen."
      ]
    },
    source: "Foliant der Feinde"
