      { name: "Schwerkraft ändern (kostet 3 Aktionen)", beschreibung: "Der Anarch wirkt den Zauber Schwerkraft umkehren. Der Zauber hat den normalen Effekt, außer, dass der Anarch den Bereich in jede beliebige Richtung ausrichten kann und Kreaturen und Objekte in Richtung des Endes des Bereichs fallen." }
