      { name: "Klauen", beschreibung: "Nahkampf Waffenangriff: +8 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 13 (2W8 + 4) Hiebschaden, plus 7 (2W6) Wuchtschaden, wenn das Ziel den Zustand liegend hat." }
