      { name: "Teleportieren", beschreibung: "Graz'zt teleportiert sich auf magische Weise, zusammen mit allen Ausrüstungsgegenständen, die er trägt oder in der Hand hält, bis zu 36 m weit in einen unbesetzten Bereich, den er sehen kann." }
