    fertigkeiten: { "Wahrnehmung": 8 },
    schadensresistenzen: ["Blitz", "Feuer", "Kälte", "Hieb-, Stich- und Wuchtschaden aus nicht-magischen Angriffen"],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Verängstigt"],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 18,
    sprachen: ["versteht Abyssisch, kann aber nicht sprechen"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/heuler.png",
    beschreibung: [
      "Ein weit entferntes Wehklagen geht der Sichtung eines Heulers voran. Selbst aus der Entfernung lässt der Klang den Verstand erschauern und erfüllt ihn mit Schrecken, wenn klar wird, dass die Quelle des Geräuschs näherkommt. Wenn Heuler auf die Jagd gehen, reicht Mut nicht aus, um sich ihnen zu stellen, und selbst die geistige Gesundheit ist gefährdet.",
      "Aufgrund der vielen Unholde, die sie einfangen und als Kriegshunde abrichten, können diese im Pandämonium heimischen Albtraumkreaturen auch auf den meisten der Unteren Ebenen angetroffen werden. Heulerrudel hetzen über die Schlachtfelder des Blutkriegs und dienen auch bösen Sterblichen, die die Macht und die Wildheit haben, über ihre Loyalität zu gebieten.",
      "Heuler verlassen sich auf ihre Geschwindigkeit, ihre Überzahl und ihr den Verstand betäubendes Heulen, um Beute in die Enge zu treiben, bevor sie sie zerreißen. Das Heulen überflutet den Verstand ihrer Opfer und macht komplexe Gedankengänge unmöglich — ganz besonders Unholde schätzen Heuler, weil ihr Heulen für ein paar entscheidende Momente in einer Schlacht die Fähigkeit eines Gegners neutralisieren kann, Zaubersprüche und andere Kräfte zu benutzen."
    ],
    besonderheiten: [
      { name: "Rudeltaktik", beschreibung: "Ein Heuler erhält einen Vorteil bei Angriffswürfen gegen eine Kreatur, wenn zumindest einer der Verbündeten des Heulers sich innerhalb von 1,50 m um die Kreatur herum befindet und der Verbündete nicht kampfunfähig ist." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Heuler führt zwei Zerfetzender Biss-Angriffe aus." },
      { name: "Zerfetzender Biss", beschreibung: "Nahkampf Waffenangriff: +6 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 10 (2W6 + 3) Stichschaden, plus 22 (4W10) psychischer Schaden, wenn das Ziel den Zustand verängstigt hat. Dieser Angriff ignoriert Schadensresistenz." },
      { name: "Verstandbrechendes Heulen (Aufladung 6)", beschreibung: "Der Heuler stößt in einem 18 m langen Kegel ein schrilles Heulen aus. Jeder Kreatur in diesem Bereich, die nicht unter dem Zustand taub leidet, muss ein Weisheitsrettungswurf gegen SG 16 gelingen, sonst erleidet sie bis zum Ende des nächsten Zugs des Heulers den Zustand verängstigt. Solange eine Kreatur auf diese Art verängstigt ist, wird ihre Bewegungsrate halbiert und sie ist kampfunfähig. Ein Ziel, dessen Rettungswurf gelingt, ist für die nächsten 24 Stunden immun gegen das Verstandbrechende Heulen aller Heuler." }
    ],
    bonusaktionen: [], reaktionen: [], legendaere_aktionen: null,
    source: "Foliant der Feinde"
