    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/hutidschin.png",
    beschreibung: [
      "Hutidschin ist ein Herzog von Cania und loyaler Diener des Mephistopheles. Er kommandiert zwei Kompanien von Höllenschlundteufeln, aus welchen Canias Aristokratie besteht. Mit solchen Soldaten unter seinem Kommando kann Hutidschin leicht jeden Rivalen vernichtend schlagen.",
      "Überall in den Höllen erfüllt Hutidschins Name die geringeren Teufel mit Furcht und Abscheu. Hutidschin hasst Sterbliche. Wird er aus den Neun Höllen beschworen, zahlt er das dem Initiator mit einem langen und qualvollen Tod heim.",
      "Mephistopheles verbietet Hutidschin, zu viele Vorstöße in die Materielle Ebene zu unternehmen, da die Abwesenheit des Herzogs ihn seinen Feinden gegenüber verwundbar zurücklässt."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für Hutidschin ist Charisma (Zauberrettungswurf-SG 22, +14 zum Treffen mit Zauberangriffen). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Blitz, Einflüsterung, Feuerwand, Gestalt verändern (kann mittelgroß werden, wenn er sein Erscheinungsbild verändert), Magie entdecken, Monster festhalten, Tote beleben, Unsichtbarkeit (nur auf sich selbst). Jeweils 3/Tag: Magie bannen. Jeweils 1/Tag: Heilung, Symbol (nur Hoffnungslosigkeit)." },
      { name: "Infernale Verzweiflung", beschreibung: "Jede Kreatur innerhalb von 4,50 m um Hutidschin herum, die kein Teufel ist, würfelt Rettungswürfe mit Nachteil." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn Hutidschin einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn zu schaffen." },
      { name: "Magieresistenz", beschreibung: "Hutidschin hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe Hutidschins sind magisch." },
      { name: "Regeneration", beschreibung: "Hutidschin erhält zu Beginn seines Zugs 20 Trefferpunkte zurück. Falls er gleißenden Schaden erleidet, funktioniert dieses Merkmal zu Beginn seines nächsten Zugs nicht. Hutidschin stirbt nur, falls er seinen Zug mit 0 Trefferpunkten beginnt und nicht regeneriert." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Hutidschin führt vier Nahkampfangriffe durch: einen mit seinem Biss, einen mit seiner Klaue, einen mit seinem Streitkolben und einen mit seinem Schwanz." },
      { name: "Biss", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 15 (2W6+8) Stichschaden. Dem Ziel muss ein Konstitutionsrettungswurf gegen SG 22 gelingen, sonst erleidet es den Zustand vergiftet. Solange es auf diese Art vergiftet ist, kann das Ziel keine Trefferpunkte zurückerlangen, und zu Beginn jedes seiner Züge erleidet es 10 (3W6) Giftschaden. Das vergiftete Ziel kann den Rettungswurf am Ende jedes seiner Züge wiederholen und bei Gelingen den Effekt auf sich selbst beenden." },
      { name: "Klaue", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 17 (2W8+8) Hiebschaden." },
      { name: "Streitkolben", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 15 (2W6+8) Wuchtschaden." },
      { name: "Schwanz", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 19 (2W10+8) Wuchtschaden." },
      { name: "Teleportieren", beschreibung: "Hutidschin teleportiert sich zusammen mit aller Ausrüstung, die er trägt oder hält, auf magische Weise bis zu 36 m weit in einen nicht besetzten Bereich, den er sehen kann." }
    ],
    bonusaktionen: [],
    reaktionen: [
      { name: "Fürchterliche Stimme (Aufladung 5-6)", beschreibung: "Nimmt Hutidschin Schaden, äußert er ein schreckliches Wort der Macht. Jeder Kreatur innerhalb von 10 m um ihn herum, die kein Teufel ist, muss ein Weisheitsrettungswurf gegen SG 22 gelingen, sonst erleidet sie 1 Minute lang den Zustand verängstigt. Eine Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und beendet bei Gelingen den Effekt auf sich selbst. Eine Kreatur, die einen erfolgreichen Rettungswurf gegen diesen Effekt ablegt, ist 24 Stunden lang immun gegen Hutidschins Fürchterliche Stimme." }
    ],
    legendaere_aktionen: [
      { name: "Angriff", beschreibung: "Hutidschin greift einmal mit seinem Streitkolben an." },
      { name: "Gewittersturm (kostet 2 Aktionen)", beschreibung: "Hutidschin lässt innerhalb eines Radius von 6 m Blitze los. Jede andere Kreatur in diesem Bereich muss einen Geschicklichkeitsrettungswurf gegen SG 22 ablegen. Bei einem misslungenen Rettungswurf erleidet sie 18 (4W8) Blitzschaden oder den halben Schaden bei einem gelungenen." },
      { name: "Teleportieren", beschreibung: "Hutidschin benutzt seine Aktion Teleportieren." }
    ],
    source: "Foliant der Feinde"
