    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Betäubt", "Bewusstlos", "Bezaubert", "Blind", "Erschöpft", "Festgesetzt", "Gelähmt", "Gepackt", "Liegend", "Taub", "Verängstigt", "Vergiftet", "Versteinert"],
