    passiveWahrnehmung: 22,
    sprachen: ["Alle", "Telepathie 36 m"],
    umgebung: ["Andere Ebenen", "Sumpf"],
    bild: "assets/images/monster/foliant/juiblex.png",
    beschreibung: [
      "Juiblex, der in uralten Grimoiren Gesichtsloser Fürst und der Sickernde Hunger genannt wird, ist der Dämonenfürst von Schleim und Schlick, eine giftige Kreatur, die sich nicht um die Intrigen und Pläne der anderen ihrer Art kümmert. Er existiert nur, um alles zu verzehren und zu verdauen und verwandelt lebende Materie in noch mehr Schleim.",
      "Juiblex ist ein wahres Grauen, eine Masse Blasen werfenden, schwarz und grün blubbernden Schleims, mit zornig starrenden roten Augen, die darin herumschwimmen. Er kann sich wie ein 6 m hoher Hügel erheben und mit tropfenden Scheinfüßen um sich schlagen, um die Getroffenen in seinen massigen Körper zu zerren. Diejenigen, die von Juiblex verzehrt werden, werden ausgelöscht.",
      "Nur die wahrhaftig Wahnsinnigen beten Juiblex an und pflegen seine Schleime und Schlicke. Diejenigen, die sich dem Dämonenfürsten darbringen, werden von ihm umschlossen und zu vage humanoiden, fühlenden Schlicken verwandelt. Die Körper dieser vormals aus Fleisch und Blut bestehenden Kreaturen bilden Juiblex' erweiterten physischen Leib, während der Dämonenfürst ihre Identitäten mit der Zeit langsam verdaut."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für Juiblex ist Charisma (Zauberrettungswurf-SG 18, +10 zum Treffen mit Zauberangriffen). Er kann die folgenden Zaubersprüche angeboren wirken, ohne dass Materialkomponenten notwendig sind. Beliebig oft: Magie entdecken, Säurespritzer (17. Grad). 3/Tag: Ansteckung, Dürre, Gasförmige Gestalt." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn Juiblex einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn dennoch zu schaffen." },
      { name: "Magische Resistenz", beschreibung: "Juiblex hat einen Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Juiblex' Waffenangriffe sind magisch." },
      { name: "Regeneration", beschreibung: "Juiblex erhält zu Beginn seines Zugs 20 Trefferpunkte zurück. Falls er Feuerschaden oder gleißenden Schaden erleidet, funktioniert dieses Merkmal zu Beginn seines nächsten Zugs nicht. Juiblex stirbt nur, falls er seinen Zug mit 0 Trefferpunkten beginnt und nicht regeneriert." },
      { name: "Spinnenklettern", beschreibung: "Juiblex kann an schwierigen Oberflächen klettern, sogar kopfüber an der Decke, ohne einen Attributswurf ablegen zu müssen." },
      { name: "Verpestet", beschreibung: "Jeder Kreatur außer einem Schlick, die ihren Zug innerhalb von 3 m um Juiblex herum beginnt, muss ein Konstitutionsrettungswurf gegen SG 21 gelingen, sonst erleidet sie bis zum Beginn ihres nächsten Zugs den Zustand vergiftet." },
      { name: "Wahnsinn des Juiblex", beschreibung: "Falls eine Kreatur in Juiblex' Hort oder im Blickfeld des Dämonenfürsten dem Wahnsinn anheimfällt, bestimmt die folgende Tabelle die Natur des Wahnsinns. Dieser ist ein Charaktermakel, der anhält, bis er geheilt wird.",
        tabelle: {
          header: ["W100", "Makel (hält an, bis er geheilt wird)"],
          rows: [
            ["01–20", '„Ich muss alles verzehren, was ich kann!"'],
            ["21–40", '„Ich weigere mich, mich von irgendeinem meiner Besitztümer zu trennen."'],
            ["41–60", '„Ich werde alles tun, was ich kann, um andere dazu zu bringen, über ihre Grenzen hinaus zu essen und zu trinken."'],
            ["61–80", '„Ich muss so viele materielle Güter besitzen, wie ich kann."'],
            ["81–00", '„Meine Persönlichkeit ist irrelevant. Ich definiere mich dadurch, was ich verzehre."']
          ]
        }
      }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Juiblex führt drei Säuregeißel-Angriffe durch." },
      { name: "Säuregeißel", beschreibung: "Nahkampf Waffenangriff: +14 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 21 (4W6+7) Säureschaden. Jede Kreatur, die von diesem Angriff getötet wird, wird in Juiblex' Körper gezerrt und die Leiche wird nach 1 Minute vollkommen vernichtet." },
      { name: "Schleim ausstoßen (Aufladung 5–6)", beschreibung: "Juiblex speit einen korrosiven Schleim aus und wählt dafür eine Kreatur als Ziel, die er innerhalb von 18 m sehen kann. Das Ziel muss einen Geschicklichkeitsrettungswurf gegen SG 21 ablegen. Bei Misslingen erleidet das Ziel 55 (10W10) Säureschaden. Wenn das Ziel dadurch Schaden erleidet, erhält jede vom Ziel getragene Metallrüstung einen permanenten Malus von −1 auf die gebotene RK, und jede Metallwaffe erhält einen permanenten Malus von −1 auf Schadenswürfe. Der Malus verschlimmert sich jedes Mal, wenn ein Ziel diesem Effekt unterworfen wird. Falls der Malus für ein Objekt auf −5 fällt, wird das Objekt zerstört." }
    ],
    bonusaktionen: [], reaktionen: [],
    legendaere_aktionen: [
      { name: "Säurespritzer", beschreibung: "Juiblex wirkt Säurespritzer." },
      { name: "Angriff", beschreibung: "Juiblex führt einen Säuregeißel-Angriff durch." },
      { name: "Verderbende Berührung (kostet 2 Aktionen)", beschreibung: "Nahkampf Waffenangriff: +14 zum Treffen, Reichweite 3 m, eine Kreatur. Treffer: 21 (4W6+7) Giftschaden, und das Ziel wird vollgeschleimt. Bis der Schleim mit einer Aktion abgekratzt wird, ist das Ziel vergiftet, und jede Kreatur außer einem Schlick erleidet den Zustand vergiftet, während sie sich innerhalb von 3 m um das Ziel herum aufhält." }
    ],
    hortaktionen: {
      beschreibung: "Bei Initiative 20 (wobei er alle Initiative-Gleichstände verliert) kann Juiblex eine Hortaktion ausführen, um einen der folgenden Effekte auszulösen; er kann denselben Effekt nicht in zwei aufeinanderfolgenden Runden benutzen:",
      aktionen: [
        "Juiblex schleimt einen quadratischen Bereich des Bodens voll, den er innerhalb des Horts sehen kann (Kanten bis zu 3 m lang). Jeder Kreatur im Bereich muss ein Stärkerettungswurf gegen SG 21 gelingen, sonst erleidet sie den Zustand festgesetzt. Kreaturen, die den Bereich erstmals betreten oder ihren Zug dort beenden, wiederholen den Wurf. Eine festgesetzte Kreatur bleibt fest, bis sie den Bereich verlässt oder sich losreißt (Aktion, STR SG 21). Falls der Schleim angezündet wird, erleidet jede Kreatur, die ihren Zug darin beginnt, 22 (4W10) Feuerschaden; nach 1 Stunde ist er verbrannt.",
        "Juiblex schleimt einen quadratischen Bereich des Bodens voll, den er innerhalb des Horts sehen kann (Kanten bis zu 3 m lang). Jeder Kreatur im Bereich muss ein Geschicklichkeitsrettungswurf gegen SG 21 gelingen, sonst erleidet sie den Zustand liegend und schlit-tert 3 m weit in eine per W8 zufällig bestimmte Richtung. Kreaturen, die den Bereich erstmals betreten oder ihren Zug dort beenden, wiederholen den Wurf. Falls der Schleim angezündet wird, erleidet jede Kreatur, die ihren Zug darin beginnt, 22 (4W10) Feuerschaden; nach 1 Stunde ist er verbrannt.",
        "Ein Grüner Schleim erscheint an einem Punkt an der Decke, den Juiblex innerhalb des Horts wählt. Der Schleim löst sich nach 1 Stunde auf."
      ]
    },
    regionale_effekte: {
      beschreibung: "Die Region, die Juiblex' Hort enthält, wird von seiner Magie verzerrt, was einen oder mehrere der folgenden Effekte verursacht:",
      effekte: [
        "Kleine Gewässer wie Teiche oder Quellen innerhalb von 1,50 km um den Hort herum werden sauer und korrodieren jedes Objekt, das sie berührt.",
        "Oberflächen innerhalb von 9 km um den Hort herum sind oft von einem dünnen Schleimfilm bedeckt, der glitschig ist und an allem klebenbleibt, was ihn berührt.",
        "Falls ein Humanoid mindestens 1 Stunde innerhalb von 1,50 km um den Hort herum verbringt, muss dieser Kreatur ein Weisheitsrettungswurf gegen SG 18 gelingen, sonst verfällt sie in einen mittels der Tabelle Wahnsinn des Juiblex festgelegten Wahnsinn. Eine Kreatur, welcher dieser Rettungswurf gelingt, kann von diesem regionalen Effekt 24 Stunden lang nicht mehr beeinflusst werden.",
        "Falls Juiblex stirbt, vergehen diese Effekte im Lauf von 1W10 Tagen."
      ]
    },
    source: "Foliant der Feinde"
