    bild: "assets/images/monster/foliant/knochenklaue.png",
    beschreibung: [
      "Ein Magier, der zu einem Lich werden will und dabei versagt, wird stattdessen möglicherweise zu einer Knochenklaue. Diese abscheulichen gackernden Untoten erhalten einige Merkmale ihrer Wunschform — doch während ein Lich zu einem unsterblichen Meister der arkanen Künste aufsteigt, dienen Knochenklauen der Dunkelheit, dem Hass und dem Schmerz.",
      "Ist der Zauberwirker magisch oder physisch zu schwach, um seine Seele in das vorbereitete Seelengefäß zu zwängen, sucht sich diese Seele einen neuen Herren — eine humanoide Kreatur im Umkreis von einigen Kilometern, deren Herz von ungewöhnlich viel Hass erfüllt ist. Die Seele verbindet sich mit der bösen Essenz dieser Kreatur, sodass die Knochenklaue für immer an die Wünsche des neuen Herren und seine unterbewussten Launen gebunden ist.",
      "Knochenklauen ergötzen sich am Morden. Wie Spinnen verstecken sich diese Kreaturen im Schatten und warten, bis ein Opfer in die Reichweite ihrer langen knöchrigen Gliedmaßen läuft. Dieses Opfer wird erst durchbohrt und dann in die Dunkelheit geschleppt. Solange ihr Herr lebt, kann die Knochenklaue nicht vernichtet werden — was immer dem Körper angetan wird, er setzt sich innerhalb weniger Stunden wieder zusammen."
    ],
    besonderheiten: [
      { name: "Erneuerung", beschreibung: "Solange ihr Herr am Leben ist, setzt sich eine zerstörte Knochenklaue in einem neuen Körper nach 1W10 Stunden wieder zusammen, und ihre Trefferpunkte werden aufgefüllt. Der neue Körper erscheint in einem Umkreis von 1,50 km von seinem Herrn entfernt." },
      { name: "Schattige Heimlichkeit", beschreibung: "Bei schwachen Lichtverhältnissen und in Dunkelheit kann die Knochenklaue die Aktion Verstecken als eine Bonusaktion ausführen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Knochenklaue führt zwei Klauenangriffe aus." },
      { name: "Durchstechende Klaue", beschreibung: "Nahkampf Waffenangriff: +8 zum Treffen, Reichweite 4,50 m, eine Kreatur. Treffer: 20 (3W10 + 4) Stichschaden. Ist das Ziel eine Kreatur, kann die Knochenklaue ihr Ziel bis zu 3 m zu sich heranziehen. Das Ziel wird gepackt (Befreiung SG 14). Die Knochenklaue hat zwei Klauen. Solange die Knochenklaue ein Ziel gepackt hält, kann sie keine anderen Ziele angreifen." },
      { name: "Schattensprung", beschreibung: "Bei schwachen Lichtverhältnissen und in Dunkelheit muss jede von der Knochenklaue ausgewählte Kreatur im Umkreis von 1,50 m einen Konstitutionsrettungswurf gegen SG 14 ablegen. Bei einem misslungenen Wurf nimmt diese Kreatur 34 (5W12 + 2) nekrotischen Schaden. Anschließend teleportiert sich die Knochenklaue magisch zu einem unbesetzten Ort, den sie im Umkreis von 18 m sehen kann. Die Knochenklaue kann sich auch mit einer gepackten Kreatur teleportieren und diese zu einem unbesetzten Ort bringen, den sie im Umkreis von 1,50 m von ihrem Ziel entfernt sehen kann. Der Zielort der Teleportation muss schwache Lichtverhältnisse haben oder dunkel sein." }
    ],
    bonusaktionen: [],
