      { name: "Säure versprühen (Aufladung 5–6)", beschreibung: "Der Kruthik sprüht Säure in einen Kegel von 4,50 m. Jede Kreatur in diesem Bereich muss einen Geschicklichkeitsrettungswurf gegen SG 14 ablegen. Bei einem misslungenen Rettungswurf erleidet die Kreatur 22 (4W10) Säureschaden oder den halben Schaden bei einem gelungenen." }
