    sprachen: [],
    umgebung: ["Wald", "Grasland", "Ruinen"],
    bild: "assets/images/monster/foliant/leichenblume.png",
    beschreibung: [
      "Leichenblumen wachsen auf Gräbern von bösen Nekromanten oder den Überresten von mächtigen Untoten. Wird ein Keimling nicht herausgerissen und verbrannt, erreicht die Leichenblume eine enorme Größe binnen weniger Wochen. Dann löst sie sich von ihrem Beet und sucht nach humanoiden Leichen auf Schlachtfeldern und Friedhöfen. Die Pflanze ist bösartig und hasst die Lebenden.",
      "Leichenblumen dünsten einen Gestank der Verwesung aus — unabhängig davon, ob sie eine Leiche verschlungen haben oder nicht. Dieser Gestank kann die Sinne von anderen Kreaturen in der Nähe überwältigen und Übelkeit verursachen."
    ],
    besonderheiten: [
      { name: "Leichen", beschreibung: "Bei der ersten Begegnung hat die Leichenblume 1W6 + 3 verschlungene humanoide Leichen in ihrem Körper. Leichenblumen können bis zu neun tote Humanoide in sich tragen. Diese Leichen haben volle Deckung gegen Angriffe und andere Effekte außerhalb der Leichenblume. Stirbt die Leichenblume, können die Leichen aus ihrem Inneren geborgen werden. Solange die Leichenblume mindestens eine Leiche in sich trägt, kann sie als Bonusaktion eine der folgenden Aktionen durchführen: (1) Die Leichenblume verdaut eine humanoide Leiche und erhält sofort 11 (2W10) Trefferpunkte. Die Leiche wird dabei vollständig aufgelöst; danach spuckt die Leichenblume die Ausrüstung der verdauten Leiche in ihrem Feld aus. (2) Die Leichenblume belebt einen toten Humanoiden in ihrem Körper und verwandelt ihn in einen Zombie. Der Zombie erscheint auf einem unbesetzten Feld im Umkreis von 1,50 m von der Leichenblume entfernt und handelt direkt nach ihr gemäß der Initiative. Der Zombie verhält sich wie ein Verbündeter der Leichenblume, wird aber nicht von ihr kontrolliert; zudem dünst er den gleichen Gestank aus wie die Blume." },
      { name: "Spinnenklettern", beschreibung: "Leichenblumen können sich auch an schwierigen Oberflächen wie Decken bewegen, ohne einen Wurf ablegen zu müssen." },
      { name: "Gestank des Todes", beschreibung: "Jede Kreatur, die ihren Zug im Umkreis von 3 m von der Leichenblume oder einem ihrer Zombies beginnt, muss einen Konstitutionsrettungswurf gegen SG 14 ablegen, sofern die Kreatur kein Konstrukt oder untot ist. Misslingt der Wurf, wird diese Kreatur bis zum Ende des Zugs kampfunfähig. Kreaturen, die immun gegen Giftschaden oder den Zustand vergiftet sind, legen automatisch einen erfolgreichen Wurf ab. Ist der Rettungswurf erfolgreich, wird die Kreatur immun gegen den Gestank aller Leichenblumen für 24 Stunden." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Leichenblume führt drei Tentakelangriffe aus." },
      { name: "Tentakel", beschreibung: "Nahkampf Waffenangriff: +5 zum Treffen, Reichweite 3 m, eine Kreatur. Treffer: 9 (2W6 + 2) Wuchtschaden; das Ziel muss einen Konstitutionsrettungswurf gegen SG 14 ablegen. Misslingt der Wurf, erleidet das Ziel 14 (4W6) Giftschaden." },
      { name: "Tote einsammeln", beschreibung: "Die Leichenblume nimmt einen ungesicherten toten Humanoiden im Umkreis von 3 m und verschlingt die Leiche mit sämtlicher Ausrüstung, die sie an oder mit sich trägt. Diese Überreste können für das Merkmal Leichen benutzt werden." }
    ],
    bonusaktionen: [], reaktionen: [], legendaere_aktionen: null,
    source: "Foliant der Feinde"
