    schadensimmunitaeten: ["Gift", "Nekrotisch", "Psychisch", "Hieb-, Stich- und Wuchtschaden aus nicht-magischen Angriffen (wenn die Waffen nicht aus Adamant bestehen)"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Gelähmt", "Verängstigt", "Vergiftet", "Versteinert"],
    sinne: ["Dunkelsicht 18 m"],
