    sprachen: ["versteht alle Sprachen, kann aber nicht sprechen"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/leichensammler.png",
    beschreibung: [
      "Als Leichensammler bekannte Kriegsmaschinen aus Urzeiten durchstreifen ziellos die öden Ebenen Acherons, bis sie von einem Nekromanten, einem General der Hobgoblins oder einem anderen bösen Kriegsherren gerufen werden, um die Ränge einer angreifenden Armee zu stärken. Diese furchtlosen Konstrukte gehorchen ihren Beschwörern, bis sie wieder nach Acheron entlassen werden. Wird der Beschwörer jedoch getötet, könnten die gerufenen Leichensammler jahrhundertelang in der Materiellen Ebene bleiben und dort auf der Suche nach einem Heimweg Leichen sammeln.",
      "Plünderer der Toten. Leichensammler gehorchen dem Ruf der Sterblichen – jedoch nur, wenn sie zu einer kürzlichen, gegenwärtigen oder bevorstehenden Schlacht gerufen werden. Sie hüllen sich in die Rüstung gefallener Krieger und nehmen deren Waffen. Die Leichen dieser Gefallenen werden auf die Lanzen und andere Waffen aufgespießt.",
      "Beschworene Berserker. Die Leichen, die sich an der Rüstung dieser Konstrukte sammeln, dienen nicht nur als makabre Kriegstrophäen. Ein Leichensammler kann die Geister gefallener Kreaturen beschwören, die an seiner Seite kämpfen und andere Kreaturen zum Aufspießen lähmen. Zwar sind die einzelnen beschworenen Geister schwach, mit ausreichend Zeit kann ein Leichensammler jedoch eine scheinbar unendliche Anzahl von Leichen beschwören.",
      "Künstliche Natur. Leichensammler müssen nicht atmen, essen, trinken oder schlafen."
    ],
    besonderheiten: [
      { name: "Magische Resistenz", beschreibung: "Der Leichensammler hat einen Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Leichensammler führt zwei Hiebangriffe aus." },
      { name: "Hieb", beschreibung: "Nahkampf-Waffenangriff: +10 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 18 (3W8+5) Wuchtschaden plus 16 (3W10) nekrotischer Schaden." },
      { name: "Lähmender Atem (Wiederaufladung 5–6)", beschreibung: "Der Leichensammler versprüht ein lähmendes Gas in einem 9-m-Kegel. Jede Kreatur in diesem Bereich muss einen Konstitutionsrettungswurf (SG 18) ablegen. Bei einem Misserfolg ist die Kreatur für 1 Minute gelähmt. Eine gelähmte Kreatur wiederholt den Rettungswurf am Ende jeder ihrer Runden; bei einem Erfolg endet der Effekt." }
    ],
    bonusaktionen: [
      { name: "Geisterhaftes Abbild (1/kurze oder lange Rast)", beschreibung: "Der Leichensammler beschwört die versklavten Geister seiner getöteten Feinde. 1W6 Geister (nicht empfindlich gegenüber Sonnenlicht) erscheinen an unbesetzten Orten im Umkreis von 4,50 m um den Leichensammler. Die Geister führen ihre Angriffe nach dem Leichensammler mit derselben Initiative aus und kämpfen bis zu ihrer Vernichtung. Wird der Leichensammler zerstört, lösen sich die Geister auf." }
    ],
