    beschreibung: [
      "Eine turmhohe Wasserwand, die Schiffe in die Tiefen des Ozeans hinabzieht und Küstensiedlungen hinwegspült — dieses Phänomen kennzeichnet die Zerstörung, die ein Leviathan auf die Welt loslassen kann. Wird er herbeigerufen, erhebt sich ein Leviathan aus einer großen Wasserfläche und bildet eine gewaltige, schlangenförmige Kreatur."
    ],
    besonderheiten: [
      { name: "Belagerungsmonster", beschreibung: "Der Leviathan verursacht doppelten Schaden gegen Gegenstände und Bauwerke (auch bei Flutwelle)." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn der Leviathan einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn zu schaffen." },
      { name: "Teilweises Einfrieren", beschreibung: "Wenn der Leviathan während desselben Zugs 50 Kälteschaden oder mehr erleidet, friert er teilweise ein; bis zum Ende seines nächsten Zugs werden seine Bewegungsraten auf 6 m reduziert und er erhält einen Nachteil auf seine Angriffswürfe." },
      { name: "Wassergestalt", beschreibung: "Der Leviathan kann den Bereich einer feindlichen Kreatur betreten und dort anhalten. Er kann einen bis zu 2,50 cm schmalen Bereich durchqueren, ohne sich quetschen zu müssen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Leviathan führt zwei Angriffe aus: einen mit seinem Hieb und einen mit seinem Schwanz." },
      { name: "Hieb", beschreibung: "Nahkampf Waffenangriff: +16 zum Treffen, Reichweite 6 m, ein Ziel. Treffer: 15 (1W10+10) Wuchtschaden plus 5 (1W10) Säureschaden." },
      { name: "Schwanz", beschreibung: "Nahkampf Waffenangriff: +16 zum Treffen, Reichweite 6 m, ein Ziel. Treffer: 16 (1W12+10) Wuchtschaden plus 6 (1W12) Säureschaden." },
      { name: "Flutwelle (Aufladung 6)", beschreibung: "Während er abgetaucht ist, erschafft der Leviathan auf magische Weise eine Wasserwand mit sich selbst als Zentrum. Die Wand ist bis zu 75 m lang, bis zu 75 m breit und bis zu 15 m tief. Wenn die Wand erscheint, müssen alle Kreaturen innerhalb ihres Bereichs einen Stärkerettungswurf gegen SG 24 ablegen. Eine Kreatur erleidet bei einem misslungenen Rettungswurf 33 (6W10) Wuchtschaden oder den halben Schaden bei einem gelungenen. Zu Beginn jedes Zugs des Leviathans, nachdem die Wand erscheint, bewegt sich die Wand zusammen mit allen anderen Kreaturen in ihr 75 m weit vom Leviathan weg. Jeder riesigen oder kleineren Kreatur innerhalb der Wand, oder deren Bereich die Wand während ihrer Bewegung durchquert, muss ein Stärkerettungswurf gegen SG 24 gelingen, sonst erleidet sie 27 (5W10) Wuchtschaden. Ansonsten erleidet sie keinen Schaden. Eine Kreatur erleidet diesen Schaden nicht öfter als einmal pro Zug. Zum Ende jedes Zugs, während dem sich die Wand bewegt, reduziert sich die Höhe der Wand um 15 m, und der Schaden, den Kreaturen in nachfolgenden Runden durch die Wand erreichen, wird um 1W10 reduziert. Sobald die Wand eine Höhe von 0 m erreicht, endet der Effekt. Eine in der Wand gefangene Kreatur kann sich schwimmend bewegen. Jedoch muss der Kreatur aufgrund der Gewalt der Welle ein Wurf auf Stärke (Athletik) gegen SG 24 gelingen, um während dieses Zugs überhaupt zu schwimmen." }
    ],
