      { name: "Klauen", beschreibung: "Nahkampf Waffenangriff: +6 zum Treffen, Reichweite 1,50 m, eine Kreatur. Treffer: 12 (2W8+3) Hiebschaden. Ist das Ziel eine Kreatur und nicht untot, muss diese einen Konstitutionsrettungswurf gegen SG 12 ablegen. Misslingt der Wurf, wird das Ziel für 1 Minute gelähmt. Eine gelähmte Kreatur kann den Rettungswurf am Ende jedes seiner Züge wiederholen. Bei einem Erfolg endet dieser Effekt." },
      { name: "Ghul wiederbeleben (Aufladen 5–6)", beschreibung: "Der Maurezhi wählt einen toten Ghul oder Grul aus, den er im Umkreis von 9 m sehen kann. Das Ziel wird wiederbelebt und erhält seine vollen Trefferpunkte." }
