    sinne: ["Dunkelsicht 36 m"],
    passiveWahrnehmung: 13,
    sprachen: ["Gemeinsprache"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/mazer.png",
    beschreibung: [
      "An Orten, wo das Shadowfell gegen die Ufer der Materiellen Ebene spült, hausen die Mazer, abscheuliche Eremiten, die ihre alten Leben hinter sich gelassen haben, um sich in den Schatten der Kontemplation ihres Elends hinzugeben. Nun brennt das Böse in ihren Herzen, und sie hassen jedes Eindringen in ihr Leiden.",
      "Abscheulicher Eremit. Mazer sind alles, was von Personen übrigbleibt, die ins Shadowfell geflohen sind, um ihrer sterblichen Existenz zu entkommen. Die Dunkelheit dort veränderte sie, und ihre Bitterkeit machte sie verschroben und grausam. Nun lungern sie in der Nähe von Shadowfell-Kreuzungen herum, um Reisenden aufzulauern, die sich zu nahe an ihre Unterschlüpfe heranwagen.",
      "Teilen und herrschen. Das Schandmal der Dunkelheit, das für die Existenz der Mazer verantwortlich ist, versah sie mit magischen Kräften, welche ihnen erlauben, sich mit Leichtigkeit durch die Schatten zu bewegen. Sie nutzen dieses Talent, um Kreaturen in den Hinterhalt zu locken, sie mit Würgeschnuren um den Hals zu drangsalieren und wegzutreten. Kreaturen, die von Mazern durch die Schatten gezerrt werden, werden von der unheilvollen Magie der Mazern verflucht. Der Fluch dient als Leuchtfeuer; Kummergeschworene, Untote und andere Schrecknisse spüren, wo die Opfer sich aufhalten und stürzen sich auf die Gestrandeten."
    ],
    besonderheiten: [
      { name: "Heimlicher Schatten", beschreibung: "Solange er sich in schwachem Licht oder Dunkelheit bewegt, kann der Mazer die Aktion Verstecken als Bonusaktion nutzen." }
    ],
    aktionen: [
      { name: "Garrotte", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,50 m, ein Ziel von der Größe des Mazers oder kleiner. Treffer: 6 (1W6+3) Wuchtschaden, und das Ziel erleidet den Zustand gepackt (Rettungswurf-SG 13 mit Nachteil zum Entkommen). Bis der Zustand gepackt endet, erleidet das Ziel zu Beginn jedes Zugs des Mazers 10 (2W6+3) Wuchtschaden. Der Mazer kann keine Waffenangriffe ausführen, solange er eine Kreatur so gepackt hält." },
      { name: "Kurzschwert", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 6 (1W6+3) Stichschaden plus 3 (1W6) nekrotischer Schaden." },
      { name: "Schattenteleportation (Wiederaufladung 5–6)", beschreibung: "Der Mazer, alle Ausrüstungsteile, die er trägt oder in der Hand hält, und jede Kreatur, die er gepackt hält, teleportieren zu einem unbesetzten Bereich innerhalb von 150 m um den Mazer herum, vorausgesetzt, dass Start- und Zielpunkt in schwachem Licht oder Dunkelheit liegen. Der Zielpunkt muss ein Ort sein, den der Mazer bereits zuvor gesehen hat, muss aber nicht in direkter Sichtlinie liegen. Falls der Zielbereich besetzt ist, führt die Teleportation zum nächstgelegenen unbesetzten Bereich. Jede andere Kreatur, die der Mazer teleportiert, wird 1 Stunde lang vom Schatten verflucht. Bis dieser Fluch endet, kann jeder Untote und jede im Shadowfell heimische Kreatur im Umkreis von 90 m um die Kreatur herum sie spüren, was es der Kreatur unmöglich macht, sich vor ihnen zu verstecken." }
    ],
