    umgebung: ["Gewässer", "Andere Ebenen"],
    bild: "assets/images/monster/foliant/merrenoloth.png",
    beschreibung: [
      "Als grimmige, hagere Kapitäne der Fähren auf dem Fluss Styx haben die Merrenoloths absolute Befehlsgewalt über ihre Fahrzeuge und stellen sicher, dass ihre Passagiere sicher ihre Ziele erreichen. Manchmal können Merrenoloths von den Unteren Ebenen weggelockt werden, um andere Wasserfahrzeuge zu kommandieren und diesen Schiffen und Besatzungen so denselben Schutz zu bieten.",
      "Wann immer ein Merrenoloth einen Vertrag annimmt, ein Schiff zu kommandieren, geht er mit dem Fahrzeug eine Verbindung ein, um sicherzustellen, dass während der Reise nichts damit schiefgeht. Ein Merrenoloth kann sein Schiff gefahrlos durch die schlimmsten Stürme navigieren, er bleibt immer auf Kurs und kommt niemals den unzähligen Fährnissen in die Quere, die schlechteren Kapitänen den Tag ruinieren können.",
      "Ein Merrenoloth kann sich durchaus seiner eigenen Haut erwehren, bevorzugt es aber wenn möglich, einen Kampf zu vermeiden. Tatsächlich spezifiziert er typischerweise in seinen Verträgen, dass er unter keinerlei Verpflichtung steht, zu kämpfen. Die oberste Pflicht eines Merrenoloths gilt immer seinem Schiff."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Merrenoloth ist Intelligenz (Zauberrettungswurf-SG 13). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Dunkelheit, Magie bannen, Magie entdecken, Person bezaubern, Windstoß. 3/Tag: Wasser kontrollieren. 1/Tag: Wetterkontrolle." },
      { name: "Magieresistenz", beschreibung: "Der Merrenoloth hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe des Merrenoloths sind magisch." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Merrenoloth benutzt einmal Furchtblick und führt einen Ruder-Angriff durch." },
      { name: "Ruder", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 8 (2W4+3) Hiebschaden." },
      { name: "Furchtblick", beschreibung: "Der Merrenoloth wählt eine Kreatur als Ziel aus, die er innerhalb von 18 m um sich herum sehen kann. Dem Ziel muss ein Weisheitsrettungswurf gegen SG 13 gelingen, sonst erhält es 1 Minute lang dem Merrenoloth gegenüber den Zustand verängstigt. Das verängstagte Ziel kann den Rettungswurf am Ende jedes seiner Züge wiederholen und bei Gelingen den Effekt auf sich selbst beenden." }
    ],
    bonusaktionen: [
      { name: "Teleport", beschreibung: "Der Merrenoloth teleportiert sich auf magische Weise zusammen mit aller Ausrüstung, die er trägt oder in der Hand hält, bis zu 18 m weit in einen nicht besetzten Bereich, den er sehen kann." }
    ],
    reaktionen: [],
    legendaere_aktionen: null,
    hortaktionen: {
      beschreibung: "Jedes Schiff, das ein Merrenoloth laut Vertrag kommandiert, wird zum Hort der Kreatur. Wenn er auf dem Schiff kämpft, kann der Merrenoloth Hortaktionen durchführen. Bei Initiative 20 (er verliert Initiative-Gleichstände) kann der Merrenoloth eine Hortaktion ausführen, um einen der folgenden Effekte auszulösen; er kann denselben Effekt nicht in zwei Runden hintereinander benutzen:",
      aktionen: [
        "Das Schiff gewinnt 22 (4W10) Trefferpunkte zurück.",
        "Ein starker Wind treibt das Schiff voran und erhöht seine Bewegungsrate bis Initiative 20 der nächsten Runde um 9 m.",
        "Die Luft innerhalb von 18 m um das Schiff herum wird von einem heulenden Wind erfüllt. Bis Initiative 20 der nächsten Runde gilt dieser Bereich als schwieriges Gelände, und wenn eine mittelgroße oder kleinere Kreatur in diesen Bereich hineinfliegt oder ihren Zug dort fliegend beginnt, muss ihr ein Stärkerettungswurf gegen SG 13 gelingen, oder sie erleidet den Zustand liegend."
      ]
    },
    regionale_effekte: {
      beschreibung: "Ein Merrenoloth erfüllt sein Schiff mit mächtiger Magie, die einen oder mehrere der folgenden Effekte auslöst:",
      effekte: [
        "Das Schiff sinkt selbst dann nicht, wenn der Rumpf leckgeschlagen ist.",
        "Das Schiff bleibt immer auf Kurs zu dem Ziel, das der Merrenoloth benennt.",
        "Den Kreaturen, die der Merrenoloth an Bord zu nehmen geruht, bereiten Wind und Wetter keine Unannehmlichkeiten, doch dieser Effekt schützt nicht gegen Schaden.",
        "Wenn der Merrenoloth stirbt, verblassen diese Effekte im Verlauf von 1W6 Stunden."
      ]
    },
    source: "Foliant der Feinde"
