    passiveWahrnehmung: 21,
    sprachen: ["alle", "Telepathie 36 m"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/moloch.png",
    beschreibung: [
      "Moloch wurde aus den Neun Höllen verbannt und würde alles dafür tun, seine Stellung wiederzuerlangen. Vor langer Zeit verdiente sich Moloch seinen Platz unter den anderen Erzteufeln durch den Ruhm beim Vertreiben von Dämonen, woraufhin Asmodeus ihn zur Herrschaft über Malbolge erhob.",
      "Das Arrangement begann sich aufzulösen, als Moloch eine Nachtvettel namens Malagard zu seiner Beraterin machte. Ihre Worte waren Gift, und allmählich überredete sie Moloch, seine Anstrengungen darauf auszurichten, Asmodeus zu stürzen. Obwohl die Verschwörung beinahe gelang, wurde sie vereitelt. Moloch wurde seiner Stellung enthoben und zum Tod verurteilt – nur ein planares Portal erlaubte ihm die Flucht.",
      "Nun ist Moloch beinahe machtlos. Er plant endlos Wege, um zu seiner früheren Stellung zurückzukehren, aber jedes Mal, wenn er die Neun Höllen betritt, wird er zum Teufelchen degradiert und kann seine normalen Kräfte nicht wiedererlangen, bevor er wieder geht. Er durchwandert die Ebenen und sucht nach magischer Macht, die ihm dabei helfen könnte, seinen Titel zurückzugewinnen."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für Moloch ist Charisma (Zauberrettungswurf-SG 21, +13 zum Treffen mit Zauberangriffen). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Brennende Hände (als Zauber des 7. Grades), Einflüsterung, Feuerwand, Fliegen, Geas, Gestalt verändern (kann mittelgroß werden, wenn er sein Erscheinungsbild verändert), Mächtiges Trugbild, Magie entdecken, Stinkende Wolke, Tote beleben, Verwirrung. Jeweils 1/Tag: Flammenschlag, Symbol (nur Betäubung)." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn Moloch einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn zu schaffen." },
      { name: "Magieresistenz", beschreibung: "Moloch hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe Molochs sind magisch." },
      { name: "Regeneration", beschreibung: "Moloch erhält zu Beginn seines Zugs 20 Trefferpunkte zurück. Falls er gleißenden Schaden erleidet, funktioniert dieses Merkmal zu Beginn seines nächsten Zugs nicht. Moloch stirbt nur, falls er seinen Zug mit 0 Trefferpunkten beginnt und nicht regeneriert." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Moloch führt drei Nahkampfangriffe durch: einen mit seinem Biss, einen mit seiner Klaue und einen mit seiner Peitsche." },
      { name: "Biss", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 26 (4W8+8) Stichschaden." },
      { name: "Klaue", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 17 (2W8+8) Hiebschaden." },
      { name: "Vielschwänzige Peitsche", beschreibung: "Nahkampf Waffenangriff: +15 zum Treffen, Reichweite 9 m, ein Ziel. Treffer: 13 (2W4+8) Hiebschaden plus 11 (2W10) Blitzschaden. Falls das Ziel eine Kreatur ist, muss ihm ein Stärkerettungswurf gegen SG 24 gelingen, sonst wird es in gerader Linie bis zu 9 m weit auf Moloch zu gezerrt." },
      { name: "Atem der Verzweiflung (Aufladung 5-6)", beschreibung: "Moloch atmet in einen Würfel mit 9 m Kantenlänge aus. Jeder Kreatur in diesem Bereich muss ein Weisheitsrettungswurf gegen SG 21 gelingen, sonst erleidet sie 27 (5W10) psychischen Schaden, lässt alles fallen, was sie in der Hand hält, und erleidet 1 Minute lang den Zustand verängstigt. Während sie auf diese Weise verängstigt ist, muss eine Kreatur die Spurt-Aktion durchführen und sich bei jedem ihrer Züge auf der gefahrlosesten verfügbaren Route von Moloch wegbewegen, außer sie kann sich nirgendwohin bewegen, in welchem Fall sie die Spurt-Aktion nicht durchführen muss. Falls die Kreatur ihren Zug an einem Ort beendet, wo sie keine direkte Sicht auf Moloch hat, kann die Kreatur den Rettungswurf wiederholen. Bei Gelingen endet der Effekt." },
      { name: "Teleportieren", beschreibung: "Moloch teleportiert sich zusammen mit aller Ausrüstung, die er trägt oder hält, auf magische Weise bis zu 36 m weit in einen nicht besetzten Bereich, den er sehen kann." }
    ],
    bonusaktionen: [],
