    bild: "assets/images/monster/foliant/nabassu.png",
    beschreibung: [
      "Die unersättlichen Nabassus durchsuchen das Multiversum nach Seelen, die sie verzehren können. Glauben sie, eine Kreatur töten und ihre Seele verzehren zu können, greifen sie an. Dabei spielt es keine Rolle, ob die Kreatur ebenfalls ein Dämon – oder gar ein anderer Nabassu – ist.",
      "Verhasst und verstoßen. Unter den Dämonen gibt es nur wenige Regeln. Dämonen, die ihresgleichen töten, können damit keinen dieser Unholde überraschen. Eine Seele zu verzehren ist dagegen etwas Anderes. Aus diesem Grund werden Nabassus aus der Gesellschaft verstoßen und in Randgebiete des Abyss gedrängt. Dort nähren sich Nabassus an schwächeren Dämonen, die sie finden können. Wenn nötig, schließen sie sich auch zu Rudeln zusammen und greifen größere Beute an. Einige besonders mächtige Nabassus begeben sich sogar auf die Suche nach Amuletten dämonischer Fürsten.",
      "Dämonische Infiltratoren. In ihrem Durst nach Seelen versuchen Nabassus, sich beschwören zu lassen, wann immer Magie Dämonen aus dem Abyss in die Materielle Ebene transportiert. Sind sie darin erfolgreich, versuchen sie, sich zu befreien und die Seele des Beschwörers – und dann die Seelen von allen Kreaturen, die sie finden können – zu verzehren. Beschwörer können sich davor schützen, indem sie den Nabassu ständig mit Seelen versorgen."
    ],
    besonderheiten: [
      { name: "Dämonische Schatten", beschreibung: "Nabassus verdunkeln den Bereich um sich im Umkreis von 3 m. Nicht-magisches Licht kann diesen schwach beleuchteten Bereich nicht erhellen." },
      { name: "Seele verzehren", beschreibung: "Nabassus können die Seele einer von ihnen getöteten Kreatur verschlingen, sofern diese nicht länger als eine Stunde tot, kein Konstrukt und kein Untoter ist. Um die Seele zu verzehren, muss sich der Nabassus im Umkreis von 1,50 m um die Kreatur für mindestens 10 Minuten aufhalten. Ist er erfolgreich, erhält er zusätzliche Trefferwürfel (W8) in Höhe der halben Anzahl der Trefferwürfel der verzehrten Kreatur. Für alle 4 Trefferwürfel, die der Dämon auf diese Weise erhält, erhöht sich der Schaden aus seinen Angriffen um zusätzliche 3 (1W6) Punkte pro Treffer. Dieser Effekt hält 6 Tage an. Eine von einem Nabassu verzehrte Kreatur kann nur durch den Zauber Wunsch wiederbelebt werden." },
      { name: "Magische Resistenz", beschreibung: "Nabassus haben einen Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Angriffe von Nabassus gelten als magisch." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Nabassu nutzt seinen Seelenraubblick und führt zwei Angriffe aus: einen Klauen- und einen Bissangriff." },
      { name: "Klauen", beschreibung: "Nahkampf Waffenangriff: +11 zum Treffen, Reichweite 1,50 m, eine Kreatur. Treffer: 17 (2W10+6) Hiebschaden." },
      { name: "Biss", beschreibung: "Nahkampf Waffenangriff: +11 zum Treffen, Reichweite 1,50 m, eine Kreatur. Treffer: 32 (4W12+6) Stichschaden." },
      { name: "Seelenraubblick", beschreibung: "Der Nabassu wählt eine Kreatur aus, die er im Umkreis von 9 m sehen kann. Kann das Ziel den Nabassu sehen, muss es einen Charismarettungswurf gegen SG 16 ablegen, sofern es kein Konstrukt oder Untoter ist. Misslingt der Wurf, sinken seine maximalen Trefferpunkte um 13 (2W12). Der Nabassu erhält temporäre Trefferpunkte in derselben Höhe. Diese Reduzierung endet nach einer kurzen oder langen Rast. Sinken die maximalen Trefferpunkte auf 0, stirbt das Ziel. Ist die Kreatur ein Humanoider, verwandelt es sich sofort in einen Ghul, der vom Nabassu kontrolliert wird." }
    ],
