    fertigkeiten: {},
    schadensresistenzen: ["Blitz", "Feuer", "Kälte", "Säure", "Schall", "Hieb-, Stich- und Wuchtschaden aus nicht-magischen Angriffen"],
    schadensimmunitaeten: ["Gift", "Nekrotisch"],
