    passiveWahrnehmung: 9,
    sprachen: [],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/nachtschreiter.png",
    beschreibung: [
      "Die Negative Ebene ist ein Ort der Dunkelheit und des Todes, Anathema für alles Lebendige. Dennoch gibt es jene, die ihre furchtbare Macht anzapfen wollen. Meistens merken solche Individuen, dass sie der Aufgabe nicht gewachsen sind, sobald sie mit diesen Energien hantieren. Wer nicht gleich vernichtet wird, wird manchmal in die Ebene gezerrt und durch einen Nachtschreiter ersetzt, schrecklichen untoten Kreaturen, die alles Leben verschlingen, dem sie begegnen.",
      "Mächtiges Gezücht. Man kann die Negative Ebene vom Shadowfell aus auf fast dieselbe Art erreichen, wie man von der Materiellen Ebene in das Shadowfell treten kann. In die Negative Ebene zu treten ist gleichbedeutend mit Selbstmord, da die Ebene das Leben und die Seele aus solch dreisten Kreaturen saugt und sie sofort auslöscht. Für jede Kreatur, die die Ebene betritt, wird ein Nachtschreiter losgelassen, der ihren Platz einnimmt.",
      "Wesen aus Anti-Leben. Man kann die Natur von Kreaturen, die in der Negativen Ebene gefangen sind, aus den Orten ableiten, die regelmäßig von Nachtschreitern aufgesucht werden. Im Allgemeinen wird ein Nachtschreiter auf der Materiellen Ebene von Elementen der Welt angezogen, die mit der Kreatur assoziiert werden, die sich für ihre Erschaffung verantwortlich zeichnet.",
      "Untote Natur. Ein Nachtschreiter benötigt weder Luft noch Nahrung, Wasser oder Schlaf."
    ],
    besonderheiten: [
      { name: "Auslöschende Aura", beschreibung: "Jede Kreatur, die ihren Zug innerhalb von 9 m um den Nachtschreiter herum beginnt, muss einen Konstitutionsrettungswurf gegen SG 21 ablegen. Misslingt der Rettungswurf, so erleidet sie 14 (4W6) nekrotischen Schaden, und der Nachtschreiter erhält bis zum Beginn ihres nächsten Zugs einen Vorteil auf Angriffswürfe gegen die Kreatur. Untote sind gegen diese Aura immun." },
      { name: "Lebensfresser", beschreibung: "Eine Kreatur, deren Trefferpunkte von durch den Nachtschreiter verursachtem Schaden auf 0 reduziert werden, stirbt und kann auf keinerlei Weise außer einem Zauber Wunsch wiederbelebt werden." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Nachtschreiter benutzt zweimal Entkräftender Fokus, oder er benutzt Entkräftender Fokus und Finger der Verdammnis, wenn verfügbar." },
      { name: "Entkräftender Fokus", beschreibung: "Nahkampf-Waffenangriff: +12 zum Treffen, Reichweite 4,50 m, ein Ziel. Treffer: 28 (5W8+6) nekrotischer Schaden. Dem Ziel muss ein Konstitutionsrettungswurf gegen SG 21 gelingen, sonst wird sein Trefferpunktemaximum um die Summe des erlittenen nekrotischen Schadens reduziert. Diese Reduktion hält an, bis das Ziel eine lange Rast beendet." },
      { name: "Finger der Verdammnis (Wiederaufladung 6)", beschreibung: "Der Nachtschreiter deutet auf eine Kreatur, die er innerhalb von 90 m um sich herum sehen kann. Dem Ziel muss ein Weisheitsrettungswurf gegen SG 21 gelingen, sonst erleidet es 26 (4W12) nekrotischen Schaden und bis zum Ende des nächsten Zugs des Nachtschreiters den Zustand verängstigt. Während die Kreatur auf diese Art verängstigt ist, ist sie ebenfalls gelähmt. Falls der Rettungswurf des Ziels gelingt, ist das Ziel für die nächsten 24 Stunden gegen den Finger der Verdammnis des Nachtschreiters immun." }
    ],
