    bild: "assets/images/monster/foliant/narzugon.png",
    beschreibung: [
      "Paladine, die Pakte mit Teufeln eingehen und ihren verdrehten Sinn für Ehre ins Leben nach dem Tod hinübertragen, sind besonders wertvoll für die Erzherzöge der Neun Höllen. Diese wollen bedingungslos gehorchende Verfechter ihrer Sache, um ihre Legionen im Krieg zu führen.",
      "Narzugons führen Lanzen aus Höllenfeuer und reiten auf Nachtmahr-Rossen wie grauenhafte Perversionen fahrender Ritter. Sie ziehen durch die infernalen Schichten und anderen Ebenen, um den Willen ihrer Herren auszuführen.",
      "Jeder Narzugon beansprucht einen Nachtmahr als sein Reittier, der durch Infernales Zaumzeug gebunden ist – ein legendärer Wundergegenstand, bestehend aus Zaum, Trense, Zügeln, Sattel, Steigbügeln und Sporen. Ein mit Infernalem Zaumzeug ausgerüsteter Nachtmahr muss jedem dienen, der die Sporen trägt, bis der Träger stirbt oder das Zaumzeug entfernt wird."
    ],
    besonderheiten: [
      { name: "Diabolisches Gespür", beschreibung: "Der Narzugon hat einen Vorteil bei Würfen auf Weisheit (Wahrnehmung), die abgelegt werden, um Kreaturen guter Gesinnung wahrzunehmen." },
      { name: "Infernales Zaumzeug", beschreibung: "Der Narzugon trägt Sporen, die Teil eines Infernalen Zaumzeugs sind, und welche ihm erlauben, seinen Nachtmahr-Gefährten zu beschwören." },
      { name: "Magieresistenz", beschreibung: "Der Narzugon hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Narzugon benutzt seinen Infernalen Befehl oder seinen Furchtbaren Befehl. Er führt auch drei Höllenfeuerlanze-Angriffe durch." },
      { name: "Höllenfeuerlanze", beschreibung: "Nahkampf Waffenangriff: +10 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 11 (1W12+5) Stichschaden plus 16 (3W10) Feuerschaden. Falls dieser Schaden eine Kreatur tötet, erhebt sich die Seele der Kreatur innerhalb von 1W4 Stunden als eine Lemure aus dem Fluss Styx in Avernus. Falls die Kreatur nicht vorher wiederbelebt wird, kann nur der Zauber Wunsch die Kreatur ins Leben zurückrufen. Ansonsten kann nur die Lemure getötet und Wahre Auferstehung auf die ursprüngliche Leiche der Kreatur gewirkt werden. Konstrukte und Teufel sind gegen diesen Effekt immun." },
      { name: "Infernaler Befehl", beschreibung: "Jeder Verbündete des Narzugons innerhalb von 18 m um ihn herum kann bis zum Ende des nächsten Zugs des Narzugons nicht bezaubert oder verängstigt werden." },
      { name: "Furchtbarer Befehl", beschreibung: "Jede Kreatur, die kein Unhold ist und ihren Zug innerhalb von 18 m um den Narzugon herum beginnt, muss einen Charismarettungswurf gegen SG 17 ablegen, sonst wird sie 1 Minute lang von dem Narzugon verängstigt. Eine Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und beendet bei Gelingen den Effekt auf sich selbst. Eine Kreatur, die einen gelungenen Rettungswurf ablegt, ist 24 Stunden lang immun gegen den Furchtbaren Befehl dieses Narzugons." },
      { name: "Heilung (1/Tag)", beschreibung: "Der Narzugon oder eine Kreatur, die er berührt, erhält bis zu 100 Trefferpunkte zurück." }
    ],
