    bild: "assets/images/monster/foliant/nupperibo.png",
    beschreibung: [
      "Keine Seele wird von den Neun Höllen abgewiesen, doch die wahrhaftig wertlosen – diejenigen, deren böse Taten im Leben mehr als alles andere aus Leichtsinn und Faulheit erwuchsen – sind nur dazu geeignet, Nupperibos zu werden. Diese erbärmlichen Kreaturen schlurfen gedankenlos durch die Landschaft: sie sind blind, aufgebläht vor nicht zu stillendem Hunger und tasten nach allen Fetzen übelriechender Substanz oder schwärmenden Ungeziefers, die sie nur in ihre ächzenden Mäuler schaufeln können.",
      "Individuell sind Nupperibos erbärmlich, doch sie sind nur selten alleine und können gefährlich sein, wenn sie sich in Rudeln versammelt haben. Sie drängen sich in Scharen zusammen, die eine lebenswichtige Passage oder ein ganzes Tal verstopfen kann. Wolken stechender Insekten, Blutmücken und anderen Ungeziefers umgeben sie wie eine furchteinflößende, stinkende Hülle, die jeden Nichtteufel quält, der sich ihnen nähert.",
      "Ein Nupperibo kennt nichts außer dem Hunger, der ihn auf eine blinde Queste nach irgendetwas treibt, das er verschlingen kann. Da er kein eigenes Interesse über das Bedürfnis hinaus besitzt, alles zu verzehren, gehorcht ein Nupperibo ohne nachzudenken jedwedem Befehl, den er telepathisch von einem anderen Teufel erhält."
    ],
    besonderheiten: [
      { name: "Hungergetrieben", beschreibung: "In den Neun Höllen können die Nupperibos jeder Kreatur einwandfrei nachspüren, die innerhalb der vergangenen 24 Stunden durch die Wolke von Ungeziefer eines Nupperibos Schaden erlitten hat." },
      { name: "Wolke von Ungeziefer", beschreibung: "Jede Kreatur, außer einem Teufel, die ihren Zug innerhalb von 6 m um einen Nupperibo herum beginnt, muss einen Konstitutionsrettungswurf gegen SG 11 ablegen. Eine Kreatur, die sich in den Bereichen zweier oder mehr Nupperibos aufhält, legt den Rettungswurf mit Nachteil ab. Bei Misslingen erleidet die Kreatur 2 (1W4) Stichschaden." }
    ],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampf Waffenangriff: +5 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 6 (1W6+3) Stichschaden." }
    ],
