      { name: "Kettenfeger", beschreibung: "Der Oger schwingt seine Kette, und jede Kreatur innerhalb von 3 m um ihn herum muss einen Geschicklichkeitsrettungswurf gegen SG 14 ablegen. Bei einem misslungenen Rettungswurf erleidet eine Kreatur 8 (1W8+4) Wuchtschaden und den Zustand liegend. Bei einem gelungenen Rettungswurf erleidet die Kreatur den halben Schaden und erhält nicht den Zustand liegend." },
      { name: "Kettenschlag (Wiederaufladung 6)", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 13 (2W8+4) Wuchtschaden, und dem Ziel muss ein Konstitutionsrettungswurf gegen SG 14 gelingen, sonst erleidet es 1 Minute lang den Zustand bewusstlos. Das bewusstlose Ziel wiederholt den Rettungswurf, falls es Schaden erleidet und am Ende jedes seiner Züge, und beendet bei Gelingen den Effekt auf sich selbst." }
