      { name: "Den Weg blockieren", beschreibung: "Bis zum Beginn des nächsten Zugs des Ogers haben Angriffswürfe gegen den Oger einen Nachteil, er hat einen Vorteil auf den Angriffswurf für einen Gelegenheitsangriff, und dieser verursacht zusätzlich 16 (3W10) Wuchtschaden bei einem Treffer. Zudem muss jedem Feind, der versucht sich ohne Teleportation aus der Reichweite des Ogers herauszubewegen, ein Stärkerettungswurf gegen SG 14 gelingen, sonst wird seine Bewegungsrate bis zum Beginn der nächsten Runde des Ogers auf 0 reduziert." }
