    attribute: { STR: 19, DEX: 17, CON: 20, INT: 17, WIS: 16, CHA: 19 },
    rettungswuerfe: { KON: 9, WEI: 7 },
    fertigkeiten: { "Einschüchtern": 8, "Täuschen": 8, "Wahrnehmung": 7 },
    schadensresistenzen: ["Blitz", "Feuer", "Kälte", "Hieb-, Stich- und Wuchtschaden durch nicht-magische Angriffe"],
    schadensimmunitaeten: ["Gift", "Säure"],
    verwundbarkeiten: [],
