    rettungswuerfe: { GES: 7, KON: 9, WEI: 6 },
    fertigkeiten: { "Heimlichkeit": 11, "Überlebenskunst": 10, "Wahrnehmung": 10 },
    schadensresistenzen: ["Kälte", "Hieb-, Stich- und Wuchtschaden durch nicht-magische Angriffe, der nicht von versilberten Waffen verursacht wird"],
    schadensimmunitaeten: ["Feuer", "Gift"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Vergiftet"],
