      { name: "Beleuchtung", beschreibung: "Der Phoenix gibt in einem Radius von 18 m helles Licht und in einem weiteren Radius von 9 m schwaches Licht ab." },
      { name: "Feuergestalt", beschreibung: "Der Phoenix kann einen bis zu 2,50 cm schmalen Bereich durchqueren, ohne sich quetschen zu müssen. Jedwede Kreatur, die den Phoenix berührt oder ihn mit einem Nahkampfangriff trifft, während sie sich innerhalb von 1,50 m um ihn herum befindet, erleidet 5 (1W10) Feuerschaden. Zusätzlich kann der Phoenix den Bereich einer feindlichen Kreatur betreten und dort anhalten. Wenn er den Bereich der Kreatur während eines Zugs zum ersten Mal betritt, erleidet diese Kreatur 5 (1W10) Feuerschaden. Der Phoenix kann auch mit einer Berührung brennbare Objekte entzünden, die nicht getragen oder in der Hand gehalten werden (benötigt keine Aktion)." },
      { name: "Feuriger Tod und Wiedergeburt", beschreibung: "Wenn der Phoenix stirbt, explodiert er. Jede Kreatur innerhalb von 18 m um ihn herum muss einen Geschicklichkeitsrettungswurf gegen SG 20 ablegen. Bei einem misslungenen Rettungswurf erleidet sie 22 (4W10) Feuerschaden oder den halben Schaden bei einem gelungenen. Das Feuer entzündet brennbare Objekte in dem Bereich, die nicht getragen oder in der Hand gehalten werden. Die Explosion vernichtet den Körper des Phoenix und hinterlässt einen eiförmigen Zinder, der 5 Pfund wiegt. Der Zinder ist glühend heiß und verursacht jeder Kreatur, die ihn berührt, 21 (6W6) Feuerschaden, jedoch nicht öfter als einmal pro Runde. Der Zinder ist immun gegen jede Art von Schaden, und nach 1W6 Tagen schlüpft aus ihm ein neuer Phoenix." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn der Phoenix einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn zu schaffen." },
      { name: "Vorbeifliegen", beschreibung: "Der Phoenix provoziert keine Gelegenheitsangriffe, wenn er aus der Reichweite eines Gegners herausfliegt." }
