    fertigkeiten: { "Athletik": 7, "Geschichte": 8, "Heimlichkeit": 8, "Wahrnehmung": 12 },
    schadensresistenzen: ["Kälte", "Nekrotisch", "Hieb-, Stich- und Wuchtschaden von nicht-magischen Angriffen"],
    schadensimmunitaeten: ["Gift"],
