    umgebung: ["Andere Ebenen", "Ruinen"],
    bild: "assets/images/monster/foliant/schaedelfuerst.png",
    beschreibung: [
      "Die Schädelfürsten haben weite Regionen des Shadowfell als ihre Domäne beansprucht. Von diesen verwüsteten Landen aus führen sie Krieg gegen ihre Rivalen und befehligen Horden der Untoten. Als kombinierte Wesen, die aus drei hasserfüllten Individuen geboren werden, verschwören sie sich andauernd gegen sich selbst.",
      "Kreaturen des Verrats. Die ersten Schädelfürsten erschienen im Nachgang von Vecnas Versuch, die Welt Greyhawk zu erobern. In der Verwirrung wandten Vecnas Kriegsfürsten sich gegeneinander. Im Zorn sammelte Vecna seine Generäle ein und band sie in Dreiergruppen zusammen – er verschmolz sie zu untoten Scheusalen, die dazu verflucht waren, sich auf ewig untereinander zu bekämpfen.",
      "Untote Natur. Ein Schädelfürst braucht keine Luft, Nahrung, Wasser oder Schlaf."
    ],
    besonderheiten: [
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Wenn der Schädelfürst einen Rettungswurf nicht schafft, kann er sich stattdessen entscheiden, ihn dennoch zu schaffen." },
      { name: "Meister des Grabes", beschreibung: "Solange er sich innerhalb von 9 m um den Schädelfürsten herum befindet, legt jeder untote Verbündete des Schädelfürsten Rettungswürfe mit Vorteil ab, und dieser Verbündete erhält 1W6 Trefferpunkte zurück, wann immer er seinen Zug dort beginnt." },
      { name: "Ausweichmanöver", beschreibung: "Wird der Schädelfürst einem Effekt unterworfen, der es ihm erlaubt, einen Geschicklichkeitsrettungswurf abzulegen, um nur den halben Schaden zu erleiden, erleidet er bei einem gelungenen Rettungswurf gar keinen Schaden, und nur halben Schaden, wenn er misslingt." },
      { name: "Zauberwirken", beschreibung: "Der Schädelfürst ist ein Zauberwirker der 13. Stufe. Sein Zauberwirkungsattribut ist Charisma (Zauberrettungswurf-SG 18, +10 zum Treffen mit Zauberangriffen). Er kennt die folgenden Zaubersprüche. Zaubertricks (beliebig oft): Feuerpfeil, Gift versprühen, Kalte Hand, Kältestrahl, Magierhand, Schockgriff. 1. Grad (4 Plätze): Donnerwoge, Magisches Geschoss, Rascher Rückzug. 2. Grad (3 Plätze): Sengender Strahl, Spiegelbilder. 3. Grad (3 Plätze): Furcht, Hast. 4. Grad (3 Plätze): Dimensionstür, Eissturm. 5. Grad (2 Plätze): Kältekegel, Todeswolke. 6. Grad (1 Platz): Böser Blick. 7. Grad (1 Platz): Finger des Todes." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Schädelfürst führt drei Angriffe mit seinem Knochen-Zauberstecken aus." },
      { name: "Knochen-Zauberstecken", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 7 (1W8+3) Wuchtschaden plus 14 (4W6) nekrotischer Schaden." }
    ],
