      { name: "Untote beschwören (kostet 3 Aktionen)", beschreibung: "Bis zu fünf Skelette oder Zombies erscheinen in unbesetzten Bereichen innerhalb von 9 m um den Schädelfürst herum und bleiben, bis sie vernichtet werden. Die Untoten würfeln Initiative und handeln beim nächsten verfügbaren Zug. Der Schädelfürst kann bis zu fünf durch diese Fähigkeit beschworene Untote gleichzeitig haben." }
