    beschreibung: [
      "Schattentänzer sind kampferprobte Schadar-Kai, die den Schatten als zweite Natur beherrschen. Mit blitzschnellen Sprüngen zwischen Dunkel und Dämmerlicht schlagen sie zu, bevor ihre Feinde reagieren können.",
      "Ihre tückischen Dornenketten können Gegner auf mehrere Arten außer Gefecht setzen — geblendet, niedergeworfen oder in eisernem Griff gefangen. Im Dienst der Rabenprinzessin durchstreifen sie die dunkelsten Winkel des Schattenfells und der Sterblichen Welt."
    ],
