    beschreibung: [
      "Wenn ein ruhmbesessener Krieger in der Schlacht fällt, ohne sich die Ehre zu verdienen, die er so verzweifelt gesucht hat, mag sein nach Kühnheit hungernder Geist das Schlachtfeld als ein Schwerttodesalb heimsuchen.",
      "Ehre über alles. Schwerttodesalben verfallen in Raserei, wenn irgendjemand ihre Tapferkeit in Frage stellt. Auf der anderen Seite lassen sie sich leicht durch Lob beschwichtigen. Städte, die in der Nähe uralter Schlachtfelder gelegen sind, halten jährliche Erinnerungsfestlichkeiten ab, um die Schwerttodesalben dort bei Laune zu halten.",
      "Untote Natur. Ein Schwerttodesalb benötigt weder Luft noch Nahrung, Wasser oder Schlaf."
    ],
