    bild: "assets/images/monster/foliant/skulk.png",
    beschreibung: [
      "Skulks sind die seelenlosen Hüllen von Reisenden, die sich im Shadowfell verirrt und jegliches Bewusstsein für sich selbst verloren haben. Ihrer Identität vollständig beraubt, sind sie dauerhaft unsichtbar geworden — nur Kinder, Spiegel und besondere Kerzen enthüllen ihre triste, haarlose Form.",
      "Ein Skulk kann durch ein Ritual beschworen werden, falls dem Wesen ein Teil der Identität des Beschwörers geschenkt wird. Der beschworene Skulk dient dann 30 Tage lang und nimmt dabei eine vage Ähnlichkeit zu seinem Herrn an. Grausam und chaotisch, führen Skulks ihre Befehle stets auf die gewalttätigste Weise aus."
    ],
    besonderheiten: [
      { name: "Fährtenlos", beschreibung: "Der Skulk hinterlässt keine Fährten, die verraten würden, wo er war oder wo er hingeht." },
      { name: "Fehlbare Unsichtbarkeit", beschreibung: "Der Skulk ist unsichtbar. Diese Unsichtbarkeit kann durch drei Dinge umgangen werden: Der Skulk erscheint als trister, glatthäutiger Humanoid, falls sein Spiegelbild in einem Spiegel oder einer anderen reflektierenden Oberfläche gesehen werden kann. Der Skulk erscheint als verschwommene, durchscheinende Gestalt im Licht einer Kerze, die aus dem ausgelassenen Fett eines Leichnams gezogen wurde, dessen Identität unbekannt ist. Humanoide Kinder von 10 Jahren oder jünger können diese Unsichtbarkeit durchschauen." }
    ],
    aktionen: [
      { name: "Klauen", beschreibung: "Nahkampfwaffenangriff: +6 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 6 (1W4+4) Hiebschaden. Falls der Skulk einen Vorteil beim Angriffswurf hat, erleidet das Ziel ebenfalls 7 (2W6) Nekrotischen Schaden." }
    ],
