      { name: "Langbogen", beschreibung: "Fernkampf Waffenangriff: +9 zum Treffen, Reichweite 45/180 m, ein Ziel. Treffer: 14 (2W8 + 5) Stichschaden plus 4 (1W8) Feuerschaden." }
