    beschreibung: [
      "Ein Stahlprädator ist eine gnadenlose Konstrukt-Maschine mit einem einzigen Zweck: sein Ziel ohne Rücksicht auf Distanz und Hindernisse aufzuspüren und zu töten. Sie werden von einem abtrünnigen Hexton-Modron in der Stadt Sigil erschaffen — gegen einen gepfefferten Preis für jeden, der einen Auftragsmörder benötigt.",
      "Sobald ein frisch angefertigter Stahlprädator aus der Maschine tritt, springt er davon und sucht seine Beute. Er spürt den Aufenthaltsort seines Ziels über Ebenengrenzen hinaus. Nach dem Töten soll er freiwillig nach Sigil zurückkehren — doch Kampfschäden können diesen Instinkt zerstören und ihn zum abtrünnigen Raubtier machen."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Stahlprädator ist Weisheit (Zauberrettungswurf-SG 15, +7 zum Treffen mit Zauberangriffen). Der Stahlprädator kann die folgenden Zauber angeboren wirken, ohne Komponenten zu benötigen: Je 3/Tag: Dimensionstür (nur selbst), Ebenenwechsel (nur auf sich selbst)." },
      { name: "Magieresistenz", beschreibung: "Der Stahlprädator hat einen Vorteil auf Rettungswürfe gegen Zauber und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe des Stahlprädators sind magisch." },
      { name: "Zielgespür", beschreibung: "Wenn dem Stahlprädator befohlen wird, ein Ziel zu jagen, kann er magisch die Richtung und Entfernung zu diesem Ziel spüren, sofern sie sich auf derselben Existenzebene befinden. Diese Wahrnehmung wird durch magische Verkleidung geblockt, nicht jedoch durch eine Formveränderung." }
    ],
