      { name: "Betäubendes Brüllen (Aufladung 5–6)", beschreibung: "Der Stahlprädator stößt in einem Kegel von 18 m ein Brüllen aus. Jede Kreatur in diesem Bereich muss einen Konstitutionsrettungswurf gegen SG 19 ablegen. Bei einem misslungenen Rettungswurf erleidet eine Kreatur 27 (5W10) Schallschaden, lässt alles fallen, was sie in der Hand hält, und erleidet 1 Minute lang den Zustand betäubt. Bei einem gelungenen Rettungswurf erleidet eine Kreatur den halben Schaden. Die betäubte Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und bei Gelingen den Effekt auf sich selbst beenden." }
