    beschreibung: [
      "Steinverfluchte entstehen durch ein widerliches alchemistisches Ritual an einem versteinerten Humanoiden. Das Gemisch aus Basiliskenblut und der Asche von Schreckhahn-Federn ruft das schwache Echo des Geistes des Opfers, erweckt die Statue zum Leben und verwandelt sie in einen loyalen Wächter.",
      "Im Kampf fahren aus den Fingern eines Steinverfluchten steinerne Klauen aus, die vor dickem grauem Schlick triefen. Dieser alchemistische Schlick kann Getroffene selbst in Statuen verwandeln. Als Teil des Erschaffungsrituals bildet sich ein faustgroßer Obsidianschädel im Inneren der Kreatur — der Nexus der Alchemie, der ein schwaches Echo der Erinnerungen des ursprünglichen Opfers enthält."
    ],
