      "Ein Larvenmagier entsteht, wenn ein mächtiger Kultist eines wurmartigen Ältesten Übels — üblicherweise ein Hexenmeister oder Zauberwirker — sich mit dem kometengetragenen Abgesandten verschmilzt. Nichts von der ursprünglichen Persönlichkeit überlebt diese Transformation; was entsteht, ist vollkommen fremdartiger Natur.",
      "Selbst wenn ein Larvenmagier scheinbar besiegt wird, ist er nicht endgültig tot: Seine Trefferpunkte auf 0 zu reduzieren lässt ihn zu einem Schwarm von Insekten zerfallen, aus dem er 24 Stunden später zurückkehrt. Nur die Vernichtung dieses Schwarmes beendet ihn dauerhaft."
