      { name: "Kometen-Zauberstecken", beschreibung: "Nahkampfwaffenangriff: +11 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 9 (1W6+6) Wuchtschaden, oder 10 (1W8+6), wenn er mit zwei Händen geführt wird, plus 18 (4W8) psychischen Schaden, und dem Ziel muss ein Konstitutionsrettungswurf gegen SG 19 gelingen, sonst wird es bis zum Ende seines nächsten Zugs kampfunfähig." },
      { name: "Psychische Kugel", beschreibung: "Fernkampfzauberangriff: +11 zum Treffen, Reichweite 36 m, ein Ziel. Treffer: 27 (5W10) psychischer Schaden." },
      { name: "Entfernungfalten (Aufladung 6)", beschreibung: "Der Seher krümmt den Raum um eine Kreatur, die er innerhalb von 10 m um sich herum sehen kann. Diese Kreatur muss einen Weisheitsrettungswurf gegen SG 19 ablegen. Misslingt der Rettungswurf, wird das Ziel zusammen mit aller Ausrüstung auf magische Weise zu einem nicht besetzten Bereich teleportiert, den der Seher sehen kann, und alle anderen Kreaturen innerhalb von 3 m um den ursprünglichen Bereich des Ziels erleiden jeweils 39 (6W12) psychischen Schaden. Gelingt der Rettungswurf, erleidet das Ziel 19 (3W12) psychischen Schaden." }
