      "Als bevorzugte Attentäter und Wächter von Sternengezücht-Kulten brillieren Verstümmler im Hinterhalt. Ihr Klauenwirbel lässt sechsfache Angriffe auf ein einzelnes Ziel niederprasseln, während sie sich blitzschnell in Sicherheit bringen."
