      { name: "Giftspritzer", beschreibung: "Erleidet der Troll Schaden irgendeiner Art außer psychischen Schadens, erleidet jede Kreatur innerhalb von 1,50 m um den Troll herum 9 (2W8) Giftschaden." },
      { name: "Regeneration", beschreibung: "Der Troll erhält zu Beginn jedes seiner Züge 10 Trefferpunkte zurück. Wenn der Troll Säure- oder Feuerschaden erleidet, funktioniert dieses Merkmal zu Beginn seines nächsten Zugs nicht. Der Troll stirbt nur, wenn er seinen Zug mit 0 Trefferpunkten beginnt und nicht regeneriert." }
