      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +7 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 11 (2W6+4) Hiebschaden plus 4 (1W8) Giftschaden." },
      { name: "Sprühgift (Aufladung 6)", beschreibung: "Der Troll schlitzt sich selbst mit einer Klaue auf und versprüht einen Nebel aus Gift in einem Würfel von 4,50 m Kantenlänge. Der Troll erleidet 7 (2W6) Hiebschaden (dieser Schaden kann auf keine Weise verringert werden). Jede Kreatur in dem Bereich muss einen Konstitutionsrettungswurf gegen SG 16 ablegen. Bei einem misslungenen Rettungswurf erleidet eine Kreatur 18 (4W8) Giftschaden und 1 Minute lang den Zustand vergiftet. Bei einem gelungenen Rettungswurf erleidet die Kreatur den halben Schaden und wird nicht vergiftet. Eine vergiftete Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und bei Gelingen den Effekt auf sich selbst beenden." }
