      "Schreckenstrolle vergrößern sich auch dadurch, dass sie Fleisch und Organe auf sich selbst verpflanzen. Wenn ein Stück zuckendes Trollfleisch auf eine frische Wunde am Schreckenstroll gebunden wird, vereinigt seine regenerative Kapazität die neue Masse mit seiner eigenen Muskulatur. Sogar noch fürchterlicher sind die vielfältigen Arme, Augen, Klauen und anderen Organe, die ein Schreckenstroll seinen Opfern ausreißt und auf sich selbst verpflanzt. Mit der Zeit können diese Kreaturen viele Gliedmaßen ansammeln."
