      { name: "Lebensgespür", beschreibung: "Der vampirische Nebel kennt den Aufenthaltsort jeder Kreatur im Umkreis von 18 m, die kein Konstrukt oder Untoter ist." },
      { name: "Verbot", beschreibung: "Der vampirische Nebel kann keinen Gebäude- oder Fahrzeugeingang betreten, ohne dazu von einer darin oder darauf befindlichen Person eingeladen worden zu sein." },
      { name: "Neblige Gestalt", beschreibung: "Der vampirische Nebel kann den Raum einer anderen Kreatur betreten und sich dort aufhalten. Außerdem kann er sich durch Öffnungen bewegen, die auch nur so klein sind, dass Luft durchpasst, obwohl er Flüssigkeiten behandelt, als seien sie festes Material. Es kostet ihn 2 zusätzliche Meter Bewegung, um 1 Meter durch Wasser zu bewegen. Der vampirische Nebel kann Objekte nicht manipulieren und kann keine anderen Kreaturen greifen oder tragen." },
      { name: "Hyperempfindlich gegenüber Sonnenlicht", beschreibung: "Der vampirische Nebel erleidet zu Beginn jedes seiner Züge 10 gleißenden Schaden, wenn er sich im Sonnenlicht befindet. Während er sich im Sonnenlicht befindet, hat er einen Nachteil auf Angriffswürfe und Attributsüberprüfungen." }
