    bild: "assets/images/monster/foliant/wastrilith.png",
    beschreibung: [
      "Wastriliths sind in den Gewässern des Abyss und anderen von der Essenz der Ebene verseuchten Wassermengen zu finden. Sie festigen ihre Macht und grausame Herrschaft als Fürsten der Tiefe.",
      "Verseucher. Wastriliths verseuchen das Wasser, in dem sie sich einnisten. Bewegen sich diese Dämonen über Land, beeinflusst ihre giftige Essenz Wasserquellen um sie herum. Das verdorbene Wasser nimmt diese Essenz auf und gehorcht den Befehlen des Wastriliths. So könnte sich die Wasseroberfläche erhärten, um Feinde an der Flucht zu hindern, oder Wogen bilden, um Opfer in die Reichweite des Dämons zu tragen.",
      "Stille Verderber. Kreaturen, die das von Wastriliths verseuchte Wasser trinken, setzen ihre Seelen aufs Spiel. Wer die giftige Flüssigkeit trinkt, könnte dahinwelken und schließlich sterben oder überleben und zu einem Diener des Chaos und des Bösen werden."
    ],
    besonderheiten: [
      { name: "Amphibie", beschreibung: "Wastriliths können sowohl an Luft als auch unter Wasser atmen." },
      { name: "Wasser verderben", beschreibung: "Zu Beginn aller Züge des Wastriliths werden alle Wasserquellen im Umkreis von 9 m vergiftet. Unter Wasser verdunkelt dieser Effekt die Umgebung leicht, bis ein Strom die Fäulnis wegträgt. Wasser in Behältern bleibt verdorben, bis es verdunstet. Eine Kreatur, die das verdorbene Wasser trinkt oder darin schwimmt, muss einen Konstitutionsrettungswurf gegen SG 18 ablegen. Ist der Rettungswurf erfolgreich, wird die Kreatur für 24 Stunden immun gegen das giftige Wasser. Misslingt der Wurf, erleidet die Kreatur 14 (4W6) Giftschaden und wird für 1 Minute vergiftet. Läuft diese Zeit ab, muss die Kreatur den Rettungswurf wiederholen. Misslingt der Wurf, erleidet die Kreatur 18 (4W8) Giftschaden und wird vergiftet, bis sie eine kurze oder lange Rast beendet. Trinkt ein anderer Dämon das verdorbene Wasser als eine Aktion, erhält er 11 (2W10) temporäre Trefferpunkte." },
      { name: "Magische Resistenz", beschreibung: "Wastriliths haben einen Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Wastrilith setzt seine Fähigkeit Greifender Strudel ein und führt drei Angriffe aus: einen Biss- und zwei Klauenangriffe." },
      { name: "Biss", beschreibung: "Nahkampf Waffenangriff: +9 zum Treffen, Reichweite 3 m, eine Kreatur. Treffer: 30 (4W12+4) Stichschaden." },
      { name: "Klauen", beschreibung: "Nahkampf Waffenangriff: +9 zum Treffen, Reichweite 3 m, eine Kreatur. Treffer: 18 (4W6+4) Hiebschaden." },
      { name: "Greifender Strudel", beschreibung: "Der Wastrilith schießt einen magischen Unterwasserstrudel auf eine Kreatur, die er im Umkreis von 18 m sehen kann. Das Ziel muss einen Stärkerettungswurf gegen SG 17 ablegen. Ist das Ziel unter Wasser, erhält es einen Nachteil auf diesen Wurf. Misslingt der Rettungswurf, erleidet es 22 (4W8+4) Säureschaden und wird 18 m an den Wastrilith herangezogen. Bei einem Erfolg wird der Schaden halbiert und die Kreatur wird nicht zum Wastrilith gezogen." }
    ],
