    passiveWahrnehmung: 11,
    sprachen: ["Tiefensprache"],
    umgebung: ["Unterirdisch"],
    bild: "assets/images/monster/foliant/wuerger.png",
    beschreibung: [
      "Würger sind unterirdische Raubtiere. Zwar würden es weder ihre Größe, noch die welligen, gummiartigen Gliedmaßen vermuten lassen, doch ihr Erscheinungsbild täuscht stark über die Gefahr, die von ihnen ausgeht, hinweg.",
      "Würger haben kein Knochenskelett und bestehen stattdessen aus Knorpelgewebe. Ihre flexible innere Struktur erlaubt es ihnen, sich leicht in einen engen Raum wie Risse und Nischen der von ihnen bewohnten Gewölbe hinein zu zwängen. Sie bleiben still und unsichtbar in ihrem Versteck und warten, bis ihre Beute vorbei kommt.",
      "Gelenkige Fänger. Normalerweise jagen die Würger ihre Beute, indem sie ihren letzten Fang direkt vor ihrem Versteck platzieren. Bekommt der Würger Hunger, verzehrt er nach und nach das tote Fleisch. Gleichzeitig weckt die Leiche die Neugier anderer humanoider Kreaturen wie Drow, Duergar und natürlich der Goblins – ihrer Lieblingsbeute.",
      "Wenn das Opfer näher kommt, schießen die sternförmigen Hände des Würgers aus dem Riss, schlingen sich um den Hals der Beute, pressen sie gegen die Felswand und würgen sie zu Tode. Dank seiner starken Arme kann ein Würger dabei in seinem Versteck außerhalb der Reichweite für andere bleiben.",
      "Einzelgänger. In der Regel jagen die Würger ihre Beute allein und bilden keine Rudel. Wo eine dieser Kreaturen ist, werden andere aber wohl nicht weit sein. Sie kommunizieren über anhaltendes unheimliches Heulen, das sogar Gestein durchdringen und auf große Entfernungen wahrnehmbar ist. In einem typischen Gewölbe ist die Quelle dieser Geräusche vor lauter Echos schwer zu bestimmen."
    ],
    besonderheiten: [
      { name: "Andersweltliche Schnelligkeit", beschreibung: "Verfügbar nach einer kurzen oder langen Rast: Der Würger kann während seines Zugs eine zusätzliche Aktion ausführen." },
      { name: "Knochenlos", beschreibung: "Der Würger kann sich mühelos durch bis zu 10 cm enge Räume bewegen." },
      { name: "Spinnenklettern", beschreibung: "Der Würger kann sich an schwierigen Oberflächen und Decken bewegen, ohne einen Wurf ablegen zu müssen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Würger greift mit zwei Tentakeln an." },
      { name: "Tentakel", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 3 m, eine Kreatur. Treffer: 5 (1W4+3) Wuchtschaden plus 3 (1W6) Stichschaden. Ist das Ziel eine große Kreatur oder kleiner, wird es gepackt (Befreiung SG 15). Bis das Ziel nicht mehr gepackt ist, gilt es als festgesetzt, und der Würger kann diesen Tentakel nicht gegen andere Ziele einsetzen. Der Würger hat zwei Tentakel. Fügt der Angriff kritischen Schaden zu, kann das Ziel zudem nicht atmen oder sprechen, bis es nicht mehr gepackt ist." }
    ],
