    attribute: { STR: 19, DEX: 14, CON: 21, INT: 16, WIS: 15, CHA: 18 },
    rettungswuerfe: { GES: 6, INT: 7, WEI: 6, CHA: 8 },
    fertigkeiten: { "Motiv erkennen": 6, "Täuschen": 8, "Überzeugen": 8, "Wahrnehmung": 6 },
    schadensresistenzen: ["Blitz", "Feuer", "Kälte", "Hieb-, Stich- und Wuchtschaden durch nicht-magische Angriffe"],
    schadensimmunitaeten: ["Gift", "Säure"],
    verwundbarkeiten: [],
