    sinne: ["Blindsicht 18 m", "Dunkelsicht 18 m"],
    passiveWahrnehmung: 16,
    sprachen: ["Abyssisch", "Infernalisch", "Telepathie 18 m"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/foliant/yagnoloth.png",
    beschreibung: [
      "Wer auch immer einen Yugoloth für eine Aufgabe unter Vertrag nehmen will, wird üblicherweise bei den Verhandlungen an einen Yagnoloth geraten. Als schlaue Unterhändler erledigen diese seltsamen Unholde das Aufsetzen von Verträgen für alle ihrer Art. Ist ein Yagnoloth einmal angeheuert, vermittelt er die Wünsche seines Arbeitgebers an die Unholde, die er befehligt.",
      "Obwohl ihnen die Führung niederer Yugoloths anvertraut ist, erhalten Yagnoloths letztendlich ihre Befehle von Arcanoloths und Ultroloths. Abgesehen von ihren eigenen Vorgesetzten haben Yagnoloths die vollständige Autorität über die Unholde unter ihrem Kommando und erwarten Gehorsam von ihnen. Ein Yagnoloth befolgt die Vorschriften in einem Vertrag, den er ausgehandelt hat, hat aber sicherlich ein Schlupfloch eingebaut, um seinen Verpflichtungen zu entkommen, wenn es die Situation rechtfertigt.",
      "Ein Yagnoloth hat einen Arm in menschlicher Größe und einen in Riesengröße, und er bedeckt immer einen davon mit einem langen Umhang. Während seiner Verhandlungen enthüllt der Yagnoloth seinen menschlichen Arm und benutzt ihn dazu, Verträge zu entwerfen und zu unterschreiben. Ist eine Machtdemonstration nötig oder tritt er in einen Kampf ein, rückt er seinen Umhang zurecht, um den Blick auf seine brutal mächtige Riesengliedmaße freizugeben."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Yagnoloth ist Charisma (Zauberrettungswurf-SG 16). Er kann die folgenden Zaubersprüche angeboren wirken, wobei keine Materialkomponenten notwendig sind: Beliebig oft: Dunkelheit, Einflüsterung, Magie bannen, Magie entdecken, Unsichtbarkeit (nur selbst). 3/Tag: Blitz." },
      { name: "Magieresistenz", beschreibung: "Der Yagnoloth hat einen Vorteil bei Rettungswürfen gegen Zaubersprüche und andere magische Effekte." },
      { name: "Magische Waffen", beschreibung: "Die Waffenangriffe des Yagnoloths sind magisch." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Yagnoloth führt entweder einen Massiver-Arm-Angriff und einen Elektrifizierte-Berührung-Angriff durch, oder er führt einen Massiver-Arm-Angriff durch und teleportiert sich vor oder nach dem Angriff." },
      { name: "Elektrifizierte Berührung", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,50 m, ein Ziel. Treffer: 27 (6W8) Blitzschaden." },
      { name: "Massiver Arm", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 4,50 m, ein Ziel. Treffer: 23 (3W12+4) Wuchtschaden. Ist das Ziel eine Kreatur, muss ihr ein Konstitutionsrettungswurf gegen SG 16 gelingen, sonst erleidet sie bis zum Ende des nächsten Zugs des Yagnoloth den Zustand betäubt." },
      { name: "Leben aussaugen", beschreibung: "Der Yagnoloth berührt eine kampfunfähige Kreatur, die sich innerhalb von 4,50 m um ihn herum befindet. Das Ziel erleidet 36 (7W8+4) nekrotischen Schaden, und der Yagnoloth erhält die Hälfte des Betrags des angerichteten Schadens an temporären Trefferpunkten. Dem Ziel muss ein Konstitutionsrettungswurf gegen SG 16 gelingen, sonst wird sein Trefferpunktemaximum um den Betrag des erlittenen Schadens reduziert. Diese Reduktion hält an, bis das Ziel eine lange Rast beendet, und das Ziel stirbt, wenn sein Trefferpunktemaximum auf 0 reduziert wird." },
      { name: "Schlachtfeldlist", beschreibung: "Aufladung 4–6. Bis zu zwei verbündete Yugoloths, die sich innerhalb von 18 m um den Yagnoloth herum aufhalten und ihn hören können, dürfen ihre Reaktionen benutzen, um jeweils einen Nahkampfangriff durchzuführen." },
      { name: "Teleport", beschreibung: "Der Yagnoloth teleportiert sich auf magische Weise zusammen mit aller Ausrüstung, die er trägt oder in der Hand hält, bis zu 18 m weit in einen nicht besetzten Bereich, den er sehen kann." }
    ],
