      "Zuggtmoy, die Dämonenkönigin der Fungi und Fürstin von Fäulnis und Verfall, ist eine fremdartige Kreatur, deren einziger Wunsch es ist, die Lebenden mit Sporen zu infizieren. Dadurch werden sie zu geistlosen Dienern transformiert und schlussendlich in einen sich zersetzenden Wirt für die Schwämme, Schimmel und anderen Pilze, die sie ausbrütet.",
      "Vollkommen nichtmenschlich, kann Zuggtmoy ihre fungoide Gestalt zur Annäherung eines humanoiden Körpers formen. Diese beinhaltet die knochendürre Figur, die in Grimoires und antiker Kunst dargestellt ist, verhangen und verschleiert von Myzelien und Flechten. In der Tat ist vieles an ihrem Erscheinungsbild, ihrem Auftreten und dem ihrer Diener eine seelenlose Verhöhnung des sterblichen Lebens und seiner vielen Facetten.",
      "Zuggtmoys Kultisten folgen ihr oft unwissentlich. Die meisten sind zu einem gewissen Grad von Pilzen infiziert, ob nun durch das Einatmen von Zuggtmoys gedankenkontrollierenden Sporen oder dadurch, dass sie bis zu dem Punkt transformiert wurden, an dem Fleisch und Fungus eins werden. Solche Kultisten sind Pilzerweiterungen des Willens der Dämonenkönigin.",
