      { name: "Befallssporen (3/Tag)", beschreibung: "Zuggtmoy stößt Sporen aus, die sich explosionsartig in einer Wolke ausbreiten, welche eine Kugel mit ihr im Zentrum von 6 m Radius ausfüllen. Die Kugel verbleibt 1 Minute lang. Jede Kreatur aus Fleisch und Blut, die sich bei deren Erscheinen in der Kugel aufhält oder sie später betritt, muss einen Konstitutionsrettungswurf gegen SG 19 ablegen. Bei einem gelungenen Rettungswurf kann die Kreatur 24 Stunden lang nicht von diesen Sporen infiziert werden. Bei einem misslungenen Rettungswurf wird die Kreatur mit einer Krankheit namens die Sporen von Zuggtmoy infiziert und erhält eine zufällige Gestalt des Wahnsinns (bestimmt durch die Tabelle Wahnsinn der Zuggtmoy), die anhält, bis die Kreatur von der Krankheit geheilt wird oder stirbt. Solange sie auf diese Weise infiziert ist, kann die Kreatur nicht erneut infiziert werden, und sie muss den Rettungswurf nach jeden vergangenen 24 Stunden wiederholen und beendet bei Gelingen die Infektion. Bei Misslingen wird der Körper der infizierten Kreatur langsam von Pilzbewuchs übernommen und nach drei solchen misslungenen Rettungswürfen stirbt die Kreatur und wird als Sporendiener wiederbelebt, wenn es sich um eine Art von Kreatur handelt, bei der dies möglich ist." },
      { name: "Gedankenkontrollsporen (Aufladung 5–6)", beschreibung: "Zuggtmoy stößt Sporen aus, die sich explosionsartig in einer Wolke ausbreiten, welche eine Kugel mit ihr im Zentrum von 6 m Radius ausfüllen. Die Kugel verbleibt 1 Minute lang. Humanoiden und Tiere, die sich bei deren Erscheinen in der Kugel aufhalten oder sie später betreten, müssen einen Weisheitsrettungswurf gegen SG 19 ablegen. Bei einem gelungenen Rettungswurf kann die Kreatur 24 Stunden lang nicht von diesen Sporen infiziert werden. Bei einem misslungenen Rettungswurf wird die Kreatur für 24 Stunden mit einer Krankheit namens der Einfluss von Zuggtmoy infiziert. Solange sie auf diese Weise infiziert ist, ist die Kreatur von Zuggtmoy bezaubert und kann von diesen Sporen nicht erneut infiziert werden." }
